function projNeedOk(P){return(!P.need||projOn(P.need))&&(!P.needEq||(S.eq[P.needEq]||0)>0)&&(!P.needLounge||loungeLv()>=P.needLounge)}   /* a work that builds on another one (the walk-in on the cold room, kitchen II on the expansion) */
