function seasonOn(){const k=S.seasonOn;return k&&(S.seasons||{})[k]!=null?k:null}
/* three sourcing contracts: a signing fee, then a fee every day it runs; its dishes sell for a little more and more
   people order them; ended at any time */
const CONTRACTS=[{k:'farm',n:'有機農場契作',sign:40000,day:900,dishes:['salad','soup','soup_x','veg','pasta','pasta_x'],d:'郊外一家小農場，每天早上送菜來：沙拉、南瓜濃湯、烤蔬菜、番茄麵。'},
 {k:'port',n:'漁港直送',sign:60000,day:1400,dishes:['salmon','seafood','risotto_x','friedrice_x','signature'],d:'每天清晨從漁港直接送：鮭魚、海鮮、海膽、蟹肉，還有招牌菜的干貝。'},
 {k:'ranch',n:'牧場直送',sign:60000,day:1400,dishes:['steak','steak_x','burger','burger_x','duck','duck_x','chicken'],d:'一家小牧場的牛、鴨和雞，整隻進、自己分切。'}];
function contractOn(k){return !!(S.contracts||{})[k]}
/* v2.4 rc7 (the player, 15:03 「產地契作看不懂什麼意思」): what a contract would bring a day, from the dishes' recent sales —
   the 8% on what they sell, and the margin on one in ten more; null when none of its dishes has sold yet */
function contractGain(C){const H=S.salesHist||{};let g=0,any=false;for(const d of C.dishes){const D=DISH(d);const n=H[d];if(!D||!(n>0))continue;any=true;const pr=d==='signature'?priceOf(d):Math.round(priceOf(d)/(1+(contractOn(C.k)?.08:0)));g+=n*pr*.08+n*.1*Math.max(0,pr*1.08-(D.cost||0))}return any?Math.round(g/10)*10:null}
function contractFee(){return CONTRACTS.filter(C=>contractOn(C.k)).reduce((a,C)=>a+C.day,0)}
/* v2.4 rc7 (the player, 14:39 「你租金要計算一下吧 但不要讓剛開始太容易倒店」): the rent, every day, for the space the
   restaurant takes — the dining room as it has been enlarged, and each space added to it: the unit next door (側廳),
   the pavement (露台), the kitchen's extension, the room at the back (Lounge), the whole floor upstairs. Small while the
   shop is small. Measured against the player's own saves (tools/sims/economy_days.py; the report has the table). */
const RENT={lv:[0,300,500,900,1500,2500],side:2000,terrace:400,kext:800,lounge:2500,up:4000};
function rentParts(){const P=[['主廳',RENT.lv[S.level]||RENT.lv[5]]];if(projOn('side'))P.push(['側廳',RENT.side]);if(projOn('terrace'))P.push(['戶外區',RENT.terrace]);if(projOn('kext'))P.push(['廚房擴建',RENT.kext]);if(loungeLv())P.push(['Lounge',RENT.lounge]);if(typeof upTaken==='function'&&upTaken())P.push(['二樓',RENT.up]);return P}
function rentToday(){return rentParts().reduce((a,p)=>a+p[1],0)}
/* the day's costs that leave the till at the end of the evening (the food was paid for in the morning) */
function dayCostsDue(){return crewWages()+rentToday()+contractFee()+Math.round((R&&R.st&&R.st.wineCost)||0)}
/* (14:46 「錢不夠付的那天 不要先欠著 前十天缺錢的話 秀琴阿姨借給我們20000 安排劇情」; rc7.2, the player, 21:57–21:58:
   「你第一天就給20,000基本上什麼東西都不用升級了…如果10天內小於300他再借3000反正每次小於300他都會借3000，但是記得要還」
   「只要你的錢超過20,000結算的時候就自動還錢」「首日贊助不用」): the till is never owed anything. In the first ten days, each
   evening that would leave less than $300 once the day's costs are paid, 秀琴阿姨 lends $3,000 at closing — as often as that
   happens, never twice in one evening. At the end of a day (the summary) with more than $20,000 left, everything owed to
   her is paid back. The till pays what it can and never goes below $0. rc7's single $20,000 loan is owed the same way. */
const LOAN=3000,LOAN_BELOW=300,LOAN_DAYS=10,REPAY_OVER=20000;
function loanState(){const L=S.loan=S.loan||{};if(L.owed==null){/* rc7: {d,n:20000,back} */L.owed=L.n&&!fact('xq_repay')&&!L.back?L.n:0;L.times=L.n?1:0}return L}
function loanOwed(){return S.loan?loanState().owed:0}
function loanNeeded(){const f=fact('xq_loan');return S.day<=LOAN_DAYS&&!(f&&f.l===S.day)&&S.money-dayCostsDue()<LOAN_BELOW}
function boostOf(d){let p=0,w=0;for(const C of CONTRACTS)if(contractOn(C.k)&&C.dishes.includes(d)){p+=.08;w+=.1}if(projOn('dryage')&&['steak','steak_x','burger','burger_x'].includes(d)){p+=.08;w+=.15}if(projOn('cellar')&&WINES[d]&&WINES[d].lv>=2)p+=.1;return{p,w}}
/* a music night: about one in three, from the day (never Math.random) */
function pianoNight(){return projOn('piano')&&(yaNight()||yaTonight())}
/* ---- rc7.4 (the player, 23:06 「酒吧要新增電視大的電視轉播運動比賽 / 這個就放在家具類，應該要200,000 / 然後電視的音響系統
   150,000」): two pieces of furniture for the Lounge. The TV stands on its console against the wall between the arch and
   the bar; on a game night (about two a week) it shows the match — a pitch, the players, the score, no team and no name —
   and people come for it. The sound system: two floor speakers and a soundbar; the game louder, music on the other nights. ---- */
const LG_FURN=[
 {k:'tv',n:'Lounge 大電視',cost:200000,ic:'lgtv',d:'拱門和吧台之間的牆邊放一台大電視。有比賽的晚上（大約一個禮拜兩晚）轉播：多兩位專程來看球的客人，吃完飯留下來的人多一點；看球的人小點點得多，最愛炸物、雞翅和起司條（有披薩的話也點披薩）。',done:'電視裝好了。有比賽的晚上會開。',jill:'先說好，不准太吵。'},
 {k:'sound',n:'電視音響系統',cost:150000,need:'tv',ic:'lgsound',d:'電視兩邊兩支落地喇叭，下面一條聲霸。比賽的晚上再多一位來看球的人，吃完留下來的人更多，看球的人也更常再點一杯；沒有比賽的晚上放音樂，吃完留下來的人也多一點。要先有大電視。',done:'喇叭接好了。轉播的時候整間 Lounge 都聽得到。',jill:'……好像太好聽了。'}];
function lgFurnOn(k){return !!(S.lgFurn&&S.lgFurn[k])}
function sportsNight(d){if(!lgFurnOn('tv')||!loungeLv())return false;d=d==null?S.day:d;return dayCoin('sport|'+d)<28}
function lgTvOn(){return sportsNight()&&phase==='service'&&!!R&&!R.closed&&loungeOpenTonight()}
const LG_TV={x0:111,x1:189,y0:50,y1:92};   /* rc8: a little narrower and further right — the staff's back door is at x 82–104 */   /* low on the wall, so a phone's ticket strip and tabs leave the screen in sight */
function drawLgTv(c,now,on,sound){const T=LG_TV;const w=T.x1-T.x0,h=T.y1-T.y0;
 c.fillStyle='rgba(0,0,0,.3)';c.fillRect(T.x0-4,T.y1+15,w+8,4);c.fillStyle='#2E2622';c.fillRect(T.x0-2,T.y1+4,w+4,12);c.fillStyle='#5A4330';c.fillRect(T.x0-2,T.y1+4,w+4,2);c.fillStyle='rgba(255,220,170,.1)';c.fillRect(T.x0,T.y1+8,w,1);
 if(sound){c.fillStyle='#161414';rr(c,T.x0+10,T.y1+.4,w-20,3.4,1.5);c.fill();for(const sx of[T.x0-12,T.x1+4]){c.fillStyle='rgba(0,0,0,.3)';c.fillRect(sx-1,T.y1+15,10,3);c.fillStyle='#1A1817';rr(c,sx,T.y0+14,8,T.y1-T.y0+3,2);c.fill();c.fillStyle='#2C2927';circ(c,sx+4,T.y0+21,2.4);circ(c,sx+4,T.y0+33,3.1);c.fillStyle='rgba(255,255,255,.07)';c.fillRect(sx+1,T.y0+15,1,T.y1-T.y0)}}
 c.fillStyle='#0E0E10';rr(c,T.x0,T.y0,w,h,2.5);c.fill();const sx0=T.x0+2.5,sy0=T.y0+2.5,sw=w-5,sh=h-5;
 if(!on){let g=c.createLinearGradient(sx0,sy0,sx0+sw,sy0+sh);g.addColorStop(0,'#1D2026');g.addColorStop(1,'#101114');c.fillStyle=g;c.fillRect(sx0,sy0,sw,sh);c.fillStyle='rgba(255,255,255,.05)';c.beginPath();c.moveTo(sx0,sy0);c.lineTo(sx0+sw*.45,sy0);c.lineTo(sx0+sw*.2,sy0+sh);c.lineTo(sx0,sy0+sh);c.closePath();c.fill();return}
 c.save();c.beginPath();c.rect(sx0,sy0,sw,sh);c.clip();
 for(let i=0;i<8;i++){c.fillStyle=i%2?'#2F7A3C':'#368544';c.fillRect(sx0+i*sw/8,sy0,sw/8+.5,sh)}
 c.strokeStyle='rgba(255,255,255,.75)';c.lineWidth=.6;c.strokeRect(sx0+3,sy0+3,sw-6,sh-6);c.beginPath();c.moveTo(sx0+sw/2,sy0+3);c.lineTo(sx0+sw/2,sy0+sh-3);c.stroke();c.beginPath();c.arc(sx0+sw/2,sy0+sh/2,6,0,7);c.stroke();c.strokeRect(sx0+3,sy0+sh/2-8,8,16);c.strokeRect(sx0+sw-11,sy0+sh/2-8,8,16);
 const bx=sx0+sw/2+Math.sin(now*.7)*sw*.32,by=sy0+sh/2+Math.sin(now*1.1+1)*sh*.28;
 for(let i=0;i<10;i++){const ax=sx0+sw*(.15+.7*((i*37%10)/10)),ay=sy0+sh*(.2+.6*((i*53%10)/10));const px=lerp(ax,bx,.25+.15*Math.sin(now*.9+i)),py=lerp(ay,by,.25+.15*Math.cos(now*.8+i));c.fillStyle=i%2?'#F2F2F2':'#D2453A';circ(c,px,py,1.3)}
 c.fillStyle='#FFFFFF';circ(c,bx,by,.9);
 c.fillStyle='rgba(10,12,16,.78)';c.fillRect(sx0+2,sy0+2,31,7);c.fillStyle='#FFFFFF';c.font=`700 5px ${FONT}`;c.textAlign='left';c.textBaseline='middle';c.fillText(`${dayCoin('sa|'+S.day)%3} : ${dayCoin('sb|'+S.day)%3}   ${Math.floor((now/2)%90)}'`,sx0+4,sy0+5.6);
 c.restore();c.fillStyle='rgba(255,255,255,.06)';c.beginPath();c.moveTo(sx0,sy0);c.lineTo(sx0+sw*.35,sy0);c.lineTo(sx0+sw*.12,sy0+sh);c.lineTo(sx0,sy0+sh);c.closePath();c.fill();
 let lg=c.createRadialGradient((T.x0+T.x1)/2,T.y1+28,4,(T.x0+T.x1)/2,T.y1+28,62);lg.addColorStop(0,'rgba(120,200,140,.12)');lg.addColorStop(1,'rgba(120,200,140,0)');c.fillStyle=lg;c.fillRect(T.x0-44,T.y1,w+88,70)}   /* rc7 (14:49 「怎樣會有人來彈鋼琴?不用付錢嗎」): only when 予安 plays — her nights, and the evening of her trial */
function extOn(k){return!!(S.ext&&S.ext[k])}
function tablesTotal(){return S.tables+(projOn('side')?(S.sideTables||0):0)+(projOn('terrace')?(S.frontTables||0):0)}
/* the street's pull on passers-by */
function extAttract(){let m=1;if(extOn('awning'))m+=.03;if(extOn('sign'))m+=.03;if(extOn('lights'))m+=.02;if(extOn('plants'))m+=.02;if(projOn('terrace'))m+=.05;if(projOn('glass'))m+=.06;if(EXTERIOR.every(e=>extOn(e.k)))m+=.03;return m}
const SIDE_TABLE_COST=[1500,2200,3000,4000,5200,6500,8000,9500,11000],FRONT_TABLE_COST=[1200,1800,2600];
/* v2.3 late game (qa1 M, the player 2026-10-01 「底下六個桌子為什麼不能升級」): 側廳卡座 — the side room's back row has always
   been four-top booths; the middle row, then the front row, can become the same booths, a whole row at a time, once
   the row is full. Same booth, same four seats as the main hall's 沙發卡座. S.sideBooths = rows converted (0–2). */
const SIDE_BOOTH_COST=[18000,24000],SIDE_ROWS=['中間那排','前面那排'],SIDE_BOOTH_DONE=['中間那排的雙人桌搬走了，換上跟後牆那排一樣的卡座。','前面那排也換好了。三排卡座，九張桌子一個樣子。'];
function sideBoothRows(){return 1+Math.min(2,Math.max(0,(S.sideBooths|0)))}
/* what to save for next: one thing within reach, one a few days away, one to dream about */
/* audit WS1-07 (2026-10-06): a goal is something tonight's shop really sells — its tab open, the item on it (Day 1 said
   「咖啡機 現在就買得起」 under a tab still grey; Day 2 the 門口花箱, Day 3 the 擴建, both not in the shop until later) */
function goalLadder(){const out=[];const money=S.money;const D=shopDay();const tabOn=n=>{const t=shopTabs().find(x=>x.n===n);return !t||t.on};
 const add=(n,cost,where,ok)=>{if(cost==null||ok===false||!tabOn(where))return;out.push({n,cost,where,left:Math.max(0,cost-money)})};
 for(const P of ALL_PROJECTS())if(!projOn(P.k)&&S.level>=P.lv&&projNeedOk(P))add(P.n,P.cost,KITCHEN_WORKS.includes(P)?'廚房設備':'店舖工程');
 for(const E of EXTERIOR)if(!extOn(E.k)&&S.level>=E.lv)add(E.n,E.cost,'家具與佈置',D>=3);
 for(const G of CATGEAR)if(!gearOn(G.k)&&!G.story&&!G.line&&G.k!=='perch'&&(!G.need||projOn(G.need))&&S.level>=(G.lv||1))add(G.n,G.cost,'貓咪生活');
 {const W=WIN_TIERS[winTier()];if(W&&projOn('side')&&S.level>=W.lv)add('窗邊貓家具：'+W.n,W.cost,'貓咪生活')}
 const nl=LEVELS[S.level];if(nl)add('擴建：'+nl.n,nl.cost,'店舖工程',!(D<4&&S.level===1));
 if(S.tables<tableCap())add('餐桌',TABLE_COST[S.tables],'家具與佈置');
 if(projOn('side')&&(S.sideTables||0)<SIDE_MAX)add('側廳桌',SIDE_TABLE_COST[S.sideTables||0],'家具與佈置');
 if(projOn('side')){const n=S.sideBooths|0;if(n<2&&(S.sideTables||0)>=(n+2)*3)add('側廳卡座：'+SIDE_ROWS[n],SIDE_BOOTH_COST[n],'家具與佈置')}
 for(const E of EQUIP){const lv=S.eq[E.k]||0;if(lv<5)add(E.n+(lv?' LV'+(lv+1):''),E.cost[lv],'廚房設備',!(E.k==='oven'&&lv===0&&D<3))}   /* the oven comes on Day 3, as the kitchen tab says */
 for(const o of OPS){const t=opsLv(o.k);if(o.tiers[t]!=null&&S.level>=o.lv&&(!o.need||o.need()))add(o.n,o.tiers[t],'店舖工程')}/* v2.3: only what can really be bought now (the Bar 小廚 waits for Lounge III) */
 {const Q=typeof loungeNext==='function'&&(fact('lounge_project')||loungeLv())?loungeNext():null;if(Q&&S.level>=Q.need)add(Q.n,Q.cost,'店舖工程')}
 for(const Dc of DECOR){const t=S.decor[Dc.k]||0;if(Dc.tiers[t]!=null&&S.level>=(Dc.tierLv?Dc.tierLv[t]:Dc.lv))add(Dc.n,Dc.tiers[t],'家具與佈置',D>=4)}
 out.sort((a,b)=>a.cost-b.cost);const near=out.find(g=>g.left===0)||out[0];const mid=out.find(g=>g.left>0&&g.left<=Math.max(3000,money*.6))||out.find(g=>g.left>0);const far=out.slice().reverse().find(g=>g.left>0&&g!==mid)||null;
 const G=[near,mid,far].filter((g,i,a)=>g&&a.indexOf(g)===i);for(const g of out.slice().reverse()){if(G.length>=3)break;if(!G.includes(g))G.push(g)}return G}
function goalLadderHTML(){const G=goalLadder();if(!G.length)return'';const avg=S.lastSummary?Math.max(1,S.lastSummary.net):1000;
 return`<h3>存錢的目標</h3><div class="card goals">${G.map(g=>{const pct=Math.min(100,Math.round(S.money/g.cost*100));const days=g.left>0?Math.max(1,Math.ceil(g.left/avg)):0;return`<div class="goal"><div class="gt"><span>${g.n}</span><small>${g.where}</small></div><div class="gb"><i style="width:${pct}%"></i></div><div class="gm">${g.left>0?`還差 ${fmt(g.left)}${days<=30?` · 照今天的收入約 ${days} 天`:''}`:'現在就買得起'}</div></div>`}).join('')}</div>`}
function flowMul(who){const t=opsLv('flow');return 1+(who==='jill'?.06:.08)*t}
