const stoveSlots=lv=>[1,2,3,3,4][lv-1]+(projOn('kext')?Math.min(2,Math.max(0,lv-3)):0)+(opsLv('pantry')?1:0);   /* the six-burner range of the kitchen expansion: LV4 → 5, LV5 → 6 */
