const barCups=lv=>lv?(lv>=3?2:1)+(projOn('kitchen2')?2:0):0;   /* kitchen II: a second coffee machine */
function ambience(){let a=0;for(const d of DECOR)a+=(S.decor[d.k]||0)*d.amb;if(projOn('glass'))a+=2;if(projOn('ceiling'))a+=3;if(projOn('catwalk'))a+=3;if(projOn('chandelier'))a+=3;if(projOn('painting'))a+=2;if(seasonOn())a+=1;if(opsLv('ac')>=2)a+=1;if(opsLv('ac')>=3)a+=2;return a+(S.level-1)}
function rating(){const r=S.reviews.slice(-Math.max(40,tablesTotal()*4));let s=3*4,n=4;for(const v of r){const w=v.w||1;s+=v.s*w;n+=w}return s/n}   /* a bigger place is judged over more visits, so one hard evening does not swing it */
function xpLv(x){return x>=55?5:x>=28?4:x>=12?3:x>=4?2:1}
const XP_T=[0,4,12,28,55];
function mLv(d){return xpLv(S.xp[d]||0)}
function priceOf(d){const D=DISH(d);return Math.round(D.price*(1+.15*(starOf(d)-1))*(S.price[d]||1)*(1+boostOf(d).p)/5)*5}   /* v2.4 rc6: the cellar, the cabinet, a contract */
function costOf(d){const D=DISH(d);let c=D.cost;if(S.today&&S.today.event==='truffle'&&D.truffle)c*=1.5;const E=S.today&&EVENTS[S.today.event];if(E&&E.costMul&&E.costMul[d])c*=E.costMul[d];return Math.round(c)}
function stockTotal(){let t=0;for(const k in S.stock)t+=S.stock[k]||0;return t}
function stSpeed(type){const lv=type==='pizza'?4:type==='stove'?S.eq.stove:type==='oven'?Math.max(1,S.eq.oven):type==='bar'?Math.max(1,S.eq.bar):S.eq.fridge;let v=SPD[clamp(lv,1,5)-1];if(type==='bar'&&S.decor.bar)v*=1.15;if(R&&R.fire>0)v*=1.4;return v}
function dishSpeed(d,type){const D=DISH(d);let v=stSpeed(type);if(D.pan)v*=1+.08*(S.eq.pan-1);return v/(1-.07*(mLv(d)-1))}
function menuList(){const m=S.menu.filter(d=>S.unlocked.includes(d)&&(!DISHES[d]||!DISHES[d].bar||loungeLv()));if(S.sigDessert&&!m.includes('sigdessert'))m.unshift('sigdessert');if(S.signature&&!m.includes('signature'))m.unshift('signature');return m}
