 c.fillStyle='#E3DDD0';el(c,0,0,8.4,5.6);let g=c.createRadialGradient(-2,-2,1,0,0,7);g.addColorStop(0,'#F3EEE2');g.addColorStop(1,'#CFC6B4');c.fillStyle=g;el(c,-.6,-.4,6.4,4.2);
