/* ================= planning a day ================= */
function applyGates(){if(S.xqJoined&&!S.xqJoinedTold){S.xqJoinedTold=1;S.news.push('<b>秀琴阿姨</b>現在是店裡的正式清潔員：收桌、洗碗都是她，照清潔員領日薪，不占員工名額。')}try{if(S.loungeProj&&S.loungeProj.state==='signing'&&!fact('lin_signed')&&S.day>=(S.loungeProj.paid||0)+3)linSigned();if(loungeOpenDue())loungeOpenNow()}catch(e){console.warn('[lounge open]',e)}if(S.sigdEvoNews&&S.sigDessert){const lv=S.sigdEvoNews;S.sigdEvoNews=0;S.news.push(`<b>招牌甜點升級了。</b>${S.sigDessert.name}賣到 ${lv===3?SIGD_EVO[2]:SIGD_EVO[1]} 份，${lv===3?'Jill 在上面拉了一層糖絲，點了金箔。':'Jill 在盤邊畫了一道果泥，放了一片薄荷。'}`)}if(S.sigEvoNews&&S.signature){const lv=S.sigEvoNews;S.sigEvoNews=0;S.news.push(`<b>招牌菜升級了。</b>${S.signature.name}賣到 ${lv===3?SIG_EVO[2]:SIG_EVO[1]} 份，Jill 把盤子重新做過：${lv===3?'食用花與金箔':'醬汁畫盤與一撮嫩葉'}，價格高 $${(lv-1)*30}。`)}
 if(S.day<=1){if(S.news21==null)S.news21=-1;if(S.news20==null)S.news20=-1}   /* audit WS1-06: the 2.0 / 2.1 notes are for saves from those versions, not a new restaurant */
 if(!S.news21&&S.day>=3){S.news21=S.day;S.news.push('<b>2.1：食物與日常。</b>做熟的菜（熟練度 LV3）可以在<b>菜單研發</b>研發成<b>特製版</b>；招牌菜賣得多會換盤；街上有人經過、有人在門口看菜單就進來；帶小孩的家庭、雨天的傘、廚房裡的空檔。')}
 if(!S.news20&&S.day>=3){S.news20=S.day;S.news.push('<b>2.0：店可以變大了。</b>主廳上方可以切到<b>店門口</b>和<b>廚房</b>（廚師真的在裡面煮）。打烊後商店裡多了<b>工程</b>（戶外區、大出菜口、冷藏庫、廚房擴建、側廳）和<b>貓的東西</b>；結算會告訴你下一個存錢的目標。')}
 if(S.news24==null){if(S.day<=1)S.news24=-1;else{S.news24=S.day;S.news.push(`<b>2.4：店裡的人，店外的生活。</b>員工有時候會因為自己的事晚點到（當天開店時會說）。幾段故事有一張插圖，看過以後在日誌「故事」的那一段可以再打開。${opsLv('room')?'營運升級的「後場休息室」現在叫<b>後場整理區</b>：廚房門邊的層架和掛鉤，一樣多兩位員工（廚師、服務生各一位）。':''}${xqHelperMode()?'Jill 認識很久的<b>秀琴阿姨</b>，每天晚上都會在快打烊時順路來幫忙收一收；請第一位清潔員，就是請她。':''}`)}}   /* v2.4: for a save that was already going — the systems only; nobody's story is told in advance */
 if(S.news24b==null){if(S.day<=1||!(S.crew||[]).length)S.news24b=-1;else{S.news24b=S.day;const lc=(S.crew||[]).filter(m=>crewPool(m)==='lounge').length;S.news.push(`<b>員工分成兩個名單。</b>餐廳員工（廚師、服務生、清潔員）和 Lounge 名單的名額各算各的，互不佔用。${loungeLv()?`Lounge 名單是固定的幾個人：${loungeLv()>=2?'Evan、沈晴、阿拓、安安、許葳':'Evan、沈晴和阿拓（Lounge II 再加兩位）'}，在「員工 › Lounge 名單」；現在 ${lc}/${loungeCap()}。`:'Lounge 蓋好以後，它有自己的名單。'}在哪裡上班照「工作分配」：服務生兩邊共用，廚房只有一個，調酒師只顧吧台。`)}}   /* v2.4 rc5: the two staff pools, told once to a save that was already going */
 if(S.news24c==null){if(S.day<=1||!poolCrew('restaurant').length)S.news24c=-1;else{S.news24c=S.day;const over=CAP_ROLES.filter(r=>roleCrew(r).length>roleCap(r));S.news.push(`<b>餐廳的名額分成三種。</b>廚師、服務生、清潔員各有自己的名額，不能互相借：廚師的名額只能聘廚師。擴建和每一個工程都寫著多哪一種。現在 ${CAP_ROLES.map(r=>`${ROLES[r].n} ${roleCrew(r).length}/${roleCap(r)}`).join('、')}${over.length?`；${over.map(r=>ROLES[r].n).join('、')}比名額多，大家都留著`:''}。${loungeLv()?'Lounge 的名單照舊。':''}`)}}   /* rc8 §21: told once to a save that was already going; nobody moves, nobody leaves */
 while(S.gate<S.day){S.gate++;const D=S.gate;
 if(D===2){unlockDish('coffee');S.eq.bar=Math.max(1,S.eq.bar);S.news.push('<b>新料理解鎖：拿鐵咖啡</b>。咖啡吧開張了，客人會加點飲料。');if(!(S.crew||[]).some(m=>!m.core&&m.pool==='restaurant'))S.news.push('現在可以請員工了：第 1 級可以請一位<b>廚師</b>、一位<b>服務生</b>（商店「員工」；開店前也能從商店請）。清潔員是<b>秀琴阿姨</b>，不占名額。')}
 if(D===3){/* audit WS1-08: the second burner comes on Day 3 for everyone — one bought in the shop the evening before is paid back */const had=S.eq.stove>=2,back=had?EQUIP.find(x=>x.k==='stove').cost[1]:0;if(S.eq.stove<2){S.eq.stove=2}if(back){S.money+=back}S.eq.prep=Math.max(1,S.eq.prep||0);unlockDish('salad');S.news.push(`<b>第二口爐子到貨！</b>同時可以做兩道熱菜。${back?`你昨天已經自己買了一台，那 ${fmt(back)} 退回來了。`:''}<br><b>冷盤台啟用：田園沙拉</b>（在砧板上切好、就在那裡裝盤，不用開火）。<br>從今天開始要自己<b>備料</b>。`)}   /* onboarding (the user, 2026-10-08: 「Day 1 HOT → PLATING、Day 2 DRINK → SERVE、Day 3 PREP → PLATING」): the cold station and the salad a day earlier, the pasta a day later — the burner stays on Day 3 (audit WS1-08) */   /* audit WS1-06: stocking was open from Day 1 and prices from Day 2 — what Day 3 changes is that the fridge is no longer filled for you */
 if(D===4){/* a save that passed Day 3 before the onboarding change had the pasta then: its cold station and salad come now */const late=!S.eq.prep;if(late){S.eq.prep=1;unlockDish('salad')}unlockDish('pasta');S.news.push(`${late?'<b>冷盤台啟用：田園沙拉</b>（在砧板上切好、就在那裡裝盤，不用開火）。<br>':''}<b>新料理：番茄義大利麵</b>（先煮麵，再加醬）。<br>今晚 19:00 會有第一次 <b>Rush Hour</b>，做好準備！`)}
 if(D===5)S.news.push('昨晚開始可以<b>裝潢與擴建</b>了。菜單研發也有更多選擇。')
 if(D===6)S.news.push('聽說<b>神秘美食評論家</b>最近會在城裡出沒…')
 if(D===8&&!S.signature)S.news.push('Jill 想做一道只屬於自己的料理。晚上可以在商店研發<b>招牌菜</b>（需要擴建到 Bistro）。')
}}
function unlockDish(d){if(!S.unlocked.includes(d))S.unlocked.push(d);if(!S.menu.includes(d)&&((DISHES[d]&&DISHES[d].bar)||menuCount()<menuCap())){S.menu.push(d);S.menuSince=S.menuSince||{};S.menuSince[d]=S.day}if(!(d in S.xp))S.xp[d]=0}
function expected(weather,event){const D=S.day;const NT=tablesTotal();let g=(3+NT*2.2)*Math.min(1.35,.85+D*.04);g*=.7+(rating()-3)*.18+.3;g*=WEATHER[weather].m*(EVENTS[event].m||1)*(S.buzz||1)*(S.signature?1.1:1)*extAttract();if(NT>=8)g=Math.min(g,NT*dayDur(D)/75);   /* a grown restaurant: a table turns over three or four times in a service at best, more people than that only queue and leave (the small early days keep their own pace) */g=Math.max(D===1?7:5,Math.round(g));
 const people=Math.round(g*1.45);const items=Math.round(people*(D<=1?1:D<=3?1.4:1.7));return{groups:g,people,items}}
function planToday(){if(S.today&&S.today.day===S.day)return;const F=feat();let weather='sun',event='none';
 if(F.events){const prev=S.wxPrev||'sun';const ww={sun:4,cloud:3,rain:2,storm:.9,hot:1.5,cool:1.6};if(prev==='rain'||prev==='storm'){ww.rain*=1.8;ww.storm*=1.5}if(prev==='hot')ww.hot*=1.8;weather=wpick(Object.keys(ww),k=>ww[k]);S.wxPrev=weather;const evs=Object.keys(EVENTS).filter(k=>!EVENTS[k].need||EVENTS[k].need());const cel=(S.stats.days+1)%10===0&&S.stats.days>0;event=cel?'celebrate':Math.random()<.38?'none':pick(evs.filter(k=>k!=='none'&&k!=='celebrate'&&(k!=='vip'||S.day>=5)))||'none'}
 const ex=expected(weather,event);S.today={day:S.day,weather,event,groups:ex.groups,people:ex.people,items:ex.items,tasks:[],reco:null};S.today.tasks=genTasks(ex);S.todayCost=S.todayCost||0}
function genTasks(ex){const D=S.day;const rw=60+D*25;const avgP=menuList().reduce((a,d)=>a+priceOf(d),0)/Math.max(1,menuList().length);
 const all=[{k:'guests',n:Math.max(3,Math.round(ex.people*.75)),t:n=>`服務 ${n} 位客人`},{k:'perfect',n:Math.max(1,Math.round(ex.items*(D<=2?.25:.3))),t:n=>`Perfect × ${n}`},{k:'revenue',n:Math.max(200,Math.round(ex.items*avgP*.65/50)*50),t:n=>`營業額 ${fmt(n)}`}];
 if(D>=3){all.push({k:'combo',n:Math.min(12,3+Math.floor(D/3)),t:n=>`達成 COMBO ×${n}`});all.push({k:'noangry',n:1,t:()=>'沒有客人生氣離開'})}
 if(D>=4){const m=menuList().filter(d=>DISH(d).cat!=='drink'&&stationOk(d));if(m.length){const exp=expectDemand(ex.groups,60);/* pick among the dishes people actually order, weighted by expected sales; ask for about 70% of that */const d=wpick(m,x=>Math.max(.2,exp[x]||0))||pick(m);const e=exp[d]||1;all.push({k:'dish',d,n:Math.max(2,Math.min(12,Math.round(e*.7))),exp:Math.round(e*10)/10,t:n=>`售出 ${DISH(d).n} × ${n}`})}}
 let chosen=D<=2?all.slice(0,3):[all[0],...all.slice(1).sort(()=>Math.random()-.5).slice(0,2)];return chosen.map(x=>({k:x.k,d:x.d,n:x.n,exp:x.exp,txt:x.t(x.n),reward:rw}))}
function taskProg(t){if(!R)return 0;const st=R.st;switch(t.k){case'guests':return st.guests;case'perfect':return st.perfect;case'revenue':return st.rev;case'combo':return R.maxCombo;case'noangry':return st.angry===0?(R.closed?1:0):0;case'dish':return st.dish[t.d]||0}return 0}
/* Advice, not a rule: what today's guests are likely to order (the ordering model itself, sampled — weather, occasion,
   recommendation and prices included), blended with what actually sold on recent days (sales plus emergency orders,
   so a sold-out day counts as the demand it really had), with a buffer for luck. */
/* v2.2: the suggested restock is a stable number for the day. It used to be re-sampled from random guests on every
   redraw of the prep screen, so pressing + (even when the purchase failed) showed a different 建議 each time. Now the
   sample is seeded by the day and the menu, and cached on S.today until either changes. */
/* v2.2.1 #1: measured on the player's Day 33 save (docs/evidence/v221_stock.md) — the ordering model is faithful to the
   simulation, but a dish's sales swing ±30% from day to day, so a flat +15% buffer left four or five dishes short every
   evening while others stayed full; the fridge cap then shaved every buffer alike; and the sales history only recorded
   what sold, so a dish that sold out was recommended *lower* the next day. Now: the buffer grows with the square root of
   the expected sales (about nine days in ten covered per dish), the history counts the demand that met an empty fridge,
   and when the fridge cannot hold the day the buffers give first and the screen says so. Demand itself is untouched. */
function suggestStock(){const ms=menuList().filter(stationOk);const T=S.today;const key=S.day+'|'+ms.join(',')+'|'+(T?T.weather+'/'+T.event+'/'+T.groups:'');if(T&&T.sugKey===key&&T.sug)return Object.assign({},T.sug);
 const mr=Math.random;const R0=rng(hash(key));Math.random=R0;let exp;try{exp=expectDemand(T?T.groups:10,120,true)}finally{Math.random=mr}const hist=S.salesHist||{};const out={},mean={};
 const lgE=loungeOpenTonight()?(3+loungeLv()*2):0;/* v2.3: the Lounge's bites have no dining demand model — a small base per dish when the Lounge opens tonight, then the sales history takes over */
 for(const d of ms){let e=exp[d]||0;if(DISHES[d]&&DISHES[d].bar)e=lgE;const h=hist[d];const m=h!=null?Math.max(e*.85,h*.55+e*.45):e;mean[d]=m;out[d]=Math.max(2,Math.ceil(m+1.2*Math.sqrt(m)+1))}
 let tot=Object.values(out).reduce((a,b)=>a+b,0);const cap=fridgeCap();let capped=0;
 if(tot>cap){const mt=Object.values(mean).reduce((a,b)=>a+b,0);const want={};if(mt<=cap){const f=(cap-mt)/Math.max(1,tot-mt);for(const d in out)want[d]=mean[d]+(out[d]-mean[d])*f}else{for(const d in out)want[d]=mean[d]*cap/mt}for(const d in out)out[d]=Math.max(1,Math.floor(want[d]));/* the rounding's leftovers go to the dishes that lost the most to the floor, so the fridge is used to the last portion */let left=cap-Object.values(out).reduce((a,b)=>a+b,0);for(const d of Object.keys(out).sort((a,b)=>(want[b]-Math.floor(want[b]))-(want[a]-Math.floor(want[a])))){if(left<=0)break;out[d]++;left--}capped=Math.round(tot)}
 if(T){T.sugKey=key;T.sug=Object.assign({},out);T.sugCapped=capped}return out}
/* what tomorrow's basic restock would cost right now (menu, stock and today's guest estimate) and how much to keep aside */
function restockEstimate(){const sug=suggestStock();let c=0;for(const d of menuList())c+=Math.max(0,(sug[d]||0)-(S.stock[d]||0))*costOf(d);return Math.round(c)}
function keepAside(){return Math.round(restockEstimate()*1.15+100)}
function shopAfterBuy(){const keep=keepAside();if(S.money<keep)toast(`⚠ 現金 ${fmt(S.money)}，可能不足以完成${S.phase==='prep'?'今天':'明天'}的建議備料（約 ${fmt(restockEstimate())}）`,'warn')}
/* v2.2: one atomic purchase path. Validate money and room, then commit; the caller gets what happened and why, so the
   screen can say 「錢不夠」 or 「冰箱空間不足」 instead of quietly doing something else. Never spends below zero. */
function stockQuote(d,want){const room=Math.max(0,fridgeCap()-stockTotal());const c=costOf(d);const byMoney=Math.floor(Math.max(0,S.money)/c);const n=Math.max(0,Math.min(want,room,byMoney));return{n,c,room,byMoney,why:n>=want?'':room<=0?'cap':byMoney<=0?'money':room<want&&byMoney>=room?'cap':'money'}}
function buyStock(d,delta){const cur=S.stock[d]||0;if(delta>0){const q=stockQuote(d,delta);if(q.n<=0){buyStock.last=q;return false}S.money-=q.n*q.c;S.todayCost+=q.n*q.c;S.stock[d]=cur+q.n;buyStock.last=q;return true}else{delta=Math.max(delta,-cur);if(delta===0){buyStock.last={n:0,why:'none'};return false}S.money+= -delta*costOf(d);S.todayCost-= -delta*costOf(d);S.stock[d]=cur+delta;buyStock.last={n:delta,why:''};return true}}
function stockFailText(d,q){return q.why==='cap'?`冰箱空間不足（還能放 ${q.room} 份，升級冰箱可以放更多）`:q.why==='money'?`錢不夠：${dishName(d)} 一份 ${fmt(q.c)}，現金 ${fmt(S.money)}`:'沒有庫存可以退'}
/* 2026-10-10 (overnight QA on the user's Day 92 save): 「一鍵補到建議量」 bought dish after dish in the menu's order until the
   fridge was full, so when it could not hold every suggestion (leftovers of dishes just taken off the menu, or of tonight's
   dishes above theirs) the whole shortfall fell on the last dishes — the ones just put on the menu, left with nothing and
   never ordered (布拉塔番茄麵 0/9, 松露南瓜濃湯 0/8, every day). The room there is now goes round tonight's dishes: each one
   with nothing gets a portion first, the rest in proportion to what each still needs (the manual: 「冰箱裝不下時會先少放
   一點」). With room for every suggestion it is every suggestion, as before. The money is still bought in the menu's order. */
function restockPlan(){const sug=suggestStock();const need={};let tot=0;for(const d in sug){const n=sug[d]-(S.stock[d]||0);if(n>0){need[d]=n;tot+=n}}
 const room=Math.max(0,fridgeCap()-stockTotal());if(tot<=room)return need;
 const out={};let left=room;for(const d in need)if(left>0&&!(S.stock[d]>0)){out[d]=1;left--}
 let rest=0;for(const d in need)rest+=need[d]-(out[d]||0);
 if(rest>0&&left>0){const f=left/rest,frac=[];for(const d in need){const r=(need[d]-(out[d]||0))*f,k=Math.floor(r);if(k>0){out[d]=(out[d]||0)+k;left-=k}frac.push([d,r-k])}
  frac.sort((x,y)=>y[1]-x[1]);for(const [d] of frac){if(left<=0)break;if((out[d]||0)<need[d]){out[d]=(out[d]||0)+1;left--}}}
 return out}
function autoStock(){const plan=restockPlan();for(const d in plan)buyStock(d,plan[d])}

/* ================= service ================= */
