/* expected sales per dish for a day like today: the guest mix and the ordering rules themselves, sampled */
function expectDemand(groups,n,est){const out={};const G=S.today?S.today.groups:groups||10;const N=n||60;
 for(let i=0;i<N;i++){const o=rollGuest();const g={type:o.type,size:o.size,reg:null,forSig:o.forSig};for(const d of orderItems(g,true))out[d]=(out[d]||0)+1}
 for(const d in out)out[d]=out[d]*G/N;return out}
function createTicket(g){const t=R.tables[g.table];if(t&&t.lounge){/* v2.3: a Lounge order — glasses from the bar, nothing from the fridge */const w=loungeOrder(g);if(!w.length){leaveGroup(g,'sad');return}const tk={id:R.tkid++,no:t.i+1,g,lounge:1,cn:g.cn?1:undefined,items:w.map(d=>({d,st:'pending',q:null,want:0,picked:false,set:null,lbar:DISH(d).wine?1:undefined})),t0:R.t};if(g.cn){/* rc7.6: the portions set aside this morning — their cost on the day, nothing from the fridge */for(const it of tk.items)if(!it.lbar){const c=costOf(it.d);S.money-=c;S.todayCost+=c}/* course by course (「一道一道上」): the portions were made in the morning — at night each course is plated behind the bar (cnp: 'plate', a moment, then ready at the L's end, never through the kitchen's stations), the second and third when the one before is eaten; each course's glass is poured when its plate is up and goes out with it (cnw) */if(g.cnCo)tk.items.forEach((it,i)=>{it.course=g.cnCo[i]||0;if(it.lbar){it.cnw=1;it.lbar=undefined}else it.cnp=1;if(it.course>0)it.st='later';else if(it.cnw)it.st='pour';else{it.st='plate';it.at=R.t+cnPlateT(g)}})}else for(const it of tk.items)if(!it.lbar&&!takeStock(it))g.short=true;if(g.tasting&&R.kt&&!R.kt.end)for(const it of tk.items)if(it.lbar&&R.kt.wines.includes(it.d)){/* rc7.6: tonight's three are Ken's to pour — a round at a time, at every seat (kenRounds), not the bartenders' */it.ktw=1;it.lbar=undefined;it.st='round';it.round=R.kt.wines.indexOf(it.d);tk.kt=1}
 tk.items=tk.items.filter(it=>it.st!=='cancel');g.ticket=tk;g.state='wait';g.pat=Math.min(1,g.pat+.12);R.tickets.push(tk);R.tv++;sfx.ticket();storyTick('order',{g,tk});try{campaignOrderLine(g,tk)}catch(e){}if(!g.chose)try{loveOrdered(g,tk)}catch(e){}return}
 let items=orderItems(g);if(!items.length&&isYJ(g)){/* v2.4: 秀琴阿姨's daughter is not sent away hungry when the fridge is empty — Jill orders in one portion for her (the opening days' emergency order, 1.5×) */items=orderItems(g,true).slice(0,1);g.yjKept=items.length?1:0}
 if(!jillStocks()&&menuList().some(d=>stationOk(d)&&(S.stock[d]||0)<=0)){/* v2.2.1: what this table would have ordered with a full fridge — the demand that hit an empty shelf goes into the sales history and the summary, so a sold-out dish is not recommended lower tomorrow */R.st.unmet=R.st.unmet||{};for(const d of orderItems(g,true))if((S.stock[d]||0)<=0)R.st.unmet[d]=(R.st.unmet[d]||0)+1}
 if(!items.length){/* nothing they wanted is left in the fridge */R.st.soldOutLeft=(R.st.soldOutLeft||0)+g.size;if(canChat('soldout',30,3))quote(g,pickT(['想吃的都賣完了。','沒東西可以點了？','下次早點來。']));noteLine(`${g.name} 想點的都賣完了，走了。`);leaveGroup(g,'sad');return}
 g.dd=items.slice();   /* v2.4 rc6 (11:49): what they had, for what goes with it later */
 const hasMain=items.some(d=>DISH(d).cat==='main');const tk={id:R.tkid++,no:t.i+1,g,items:items.map(d=>{const cat=DISH(d).cat;const set=hasMain&&(cat==='drink'||cat==='dessert')&&setFor(cat)||null;return{d,st:'pending',q:null,want:d==='steak'?wpick([0,1,2,3],k=>[.2,.35,.3,.15][k]):0,picked:false,set,lbar:cat==='wine'&&loungeLv()?1:undefined,dinw:cat==='wine'&&!loungeLv()?1:undefined,kept:g.yjKept?1:undefined}}),t0:R.t};for(const it of tk.items)if(it.dinw){it.st='ready';it.q='G'}   /* rc8: before the Lounge a pairing glass is poured at the pass at once */
 if(g.reg&&g.reg!=='dylan'){const ids=regsOf(g);tk.items.forEach((it,i)=>{const m=regMem(ids[Math.min(i,ids.length-1)]||g.reg);m.orders[it.d]=(m.orders[it.d]||0)+1});if(g.share&&tk.items.some(i=>DISH(i.d).cat==='dessert')&&Math.random()<.5)speakLater(()=>{if(R&&phase==='service'&&R.groups.includes(g))quote(g,'一份甜點，兩支叉子。')},800)}
 for(const it of tk.items)if(!it.lbar&&!it.dinw&&!takeStock(it))g.short=true;tk.items=tk.items.filter(it=>it.st!=='cancel');if(tk.items.some(it=>it.st==='order')){toast(`食材不夠！Jill 緊急叫貨中（1.5 倍價），${g.name} 要多等一下`);g.pat=Math.min(1,g.pat+.1)}stockWatch();
 g.ticket=tk;g.state='wait';g.pat=Math.min(1,g.pat+.12);R.tickets.push(tk);R.tv++;sfx.ticket();campaignOrder(tk);try{campaignOrderLine(g,tk)}catch(e){}{const tp=socialTopic();if(tp&&tp.k==='food'&&tp.dish&&tk.items.some(i=>i.d===tp.dish)&&Math.random()<.3&&canChat('topic',90,4)){const dn=dishName(tp.dish);quote(g,pickT([`${dn}，網路上那個？`,`我看到有人發${dn}的照片。`,`聽說${dn}很好吃。`]))}}/* v2.3; rc8.5: the dish named — 「是不是那一道？」 said nothing on its own */
 if(g.reg==='dylan'){dylanOrdered(g,tk)}else if(loveOrdered(g,tk)){/* rc7.4: said what they love (or missed it) */}else if(g.reg){const who=speakerOf(g);const v=S.regulars[who]||0;const tier=Math.floor(regTier(v));/* not every visit: a line when they are still new, then only now and then */if(tier===0?Math.random()<.5:Math.random()<.35){const t=regTalk(who,tier);const M=S.chatSeen||{};if(t&&!(M[t]!=null&&S.day-M[t]<CHAT_DAYS)){quote(g,t,{who});(S.chatSeen=S.chatSeen||{})[t]=S.day}}   /* rc8.5: a regular's everyday words, not again within the week (「Jill，今天的醬汁我想再試一次。」 two days apart) */}else if(g.type==='vip'&&anonG(g))quote(g,pickH(VIP_ORDER,'vip|'+S.day+'|'+g.id));else if(!g.zhouUsual&&Math.random()<.12){const nn=namedId(g);quote(g,pickT(nn&&(namedHist(nn).v||0)>0?ORDER_KNOWN:ORDER_NEW))}   /* audit N03: a named guest is 「known」 once she has been here before, not on her first evening; 周董's own 「隨便」 is his order */
 storyTick('order',{g,tk});   /* v2.3 */
 coach(2)}
/* v2.4 rc6 (09:39): the VIPs order in their own words, not one sentence for all of them; a named guest who has been here
   before does not ask what a first-timer asks */
const VIP_ORDER=['把你們最好的端上來吧。','今天有什麼特別的？','招牌的都上一份。','不用看菜單了，照你們推薦的來。','有什麼是今天才有的？','先來一杯，菜慢慢上。','今天不趕時間，慢慢上。','好吃的都來。'];
const ORDER_NEW=['今天想吃點好的。','聽說這裡的東西都是 Jill 親手做的？','有推薦的嗎？算了，都點吧。','每一道都想吃，好難選。','先點這些，不夠再加。','看了好久，就這幾道。'];
const ORDER_KNOWN=['今天想吃點好的。','先點這些，不夠再加。','上次那道很好，今天換一道。','今天胃口很好。','老樣子，再加一道沒吃過的。'];
const SEAT_KNOWN=['又來了。','還是這裡舒服。','今天人好多。','先坐一下，等等再點。','今天想坐久一點。','今天的燈好舒服。'];
function recipeOf(d){return DISH(d).steps}
function uniq(a){return[...new Set(a)]}
function zoneQ(p,z){if(p>=1)return'O';const d=Math.abs(p-z.c);return d<=z.w?'P':d<=z.g?'G':'O'}
function decoyFor(d,items){if(S.day<3||Math.random()<.4||items.some(i=>i.startsWith('s_')))return[];const st=DISH(d).st;const pool=new Set();for(const x of S.unlocked.concat(S.signature?['signature']:[],S.sigDessert?['sigdessert']:[])){const D=DISH(x);if(!D||D.st!==st)continue;for(const s2 of D.steps)if(s2.t==='add')s2.items.forEach(i=>{if(!i.startsWith('s_'))pool.add(i)})}items.forEach(i=>pool.delete(i));const arr=[...pool];return arr.length?[pick(arr)]:[]}
function enterStep(j,i){const st=recipeOf(j.d)[i];const m=mLv(j.d);const k=Object.assign({},st,{p:0,cnt:0,taps:0,mis:0,t0:R.t,scorch:0,last:R.t,hold:false,level:0,auto:0});
 if(st.t==='add'){k.left=st.items.slice();k.btns=shuffle(st.items.concat(decoyFor(j.d,st.items)))}
 if(st.t==='tap')k.n=Math.max(3,st.n-(m-1));
 const V=stepVar(j,i);
 if(st.t==='zone'){const c=(st.c==='want'?[.52,.66,.8,.93][j.it.want]:st.c)+(st.c==='want'?0:V.shift*.6);let w=st.w*(1+.12*(m-1))*V.width;if(DISH(j.d).pan)w*=1+.1*(S.eq.pan-1);if(st.c==='want')w=Math.min(w,.065);k.z={c,w,g:w+.12}}
 if(st.t==='hold'){const wd=.015*(m-1);const mid=(st.a+st.b)/2+V.shift,half=(st.b-st.a)/2*V.width;k.a=Math.max(.05,mid-half-wd);k.b=Math.min(.97,mid+half+wd);k.rate=st.rate*V.rate}
 if(st.t==='work'){k.n=8;k.taps=0;k.wt=0}
 j.si=i;j.step=k}
/* The target of a hold or a flip moves a little: mostly by the day (today's beans grind coarser, today's cream is
   thicker) and a touch per plate. The band on the tray shows the real target, so the hand learns the recipe and the
   eyes do the last bit. Steak doneness is exact — a customer asked for it. */
function stepVar(j,i){const hd=hash(S.day+'|'+j.d+'|'+i),hj=hash(j.seed+'|'+i);const u=(h,k)=>((h>>>(k*8))&255)/255;
 const shift=(u(hd,0)-.5)*.09+(u(hj,0)-.5)*.03;const width=.85+u(hd,1)*.3;const rate=.9+u(hd,2)*.22;return{shift,width,rate}}
function newJob(tk,it){const j={tk,it,d:it.d,si:0,step:null,scores:[],adds:[],t0:R.t,side:0,sear:[0,0],lastZone:0,mix:0,fill:0,wait:0,overStart:null,overLimit:0,overIdx:-1,overVerb:'',seed:(Math.random()*1e9)|0};enterStep(j,0);return j}
function cookNow(j){return j.step&&j.step.t==='zone'?j.step.p:j.lastZone}
function urgency(j){const k=j.step;if(!k)return 0;if(j.overStart!=null)return 4;if(k.t==='wait'||k.t==='work')return 0;if(k.t==='zone')return k.p>=k.z.c-k.z.g-.12?3:1;if(k.t==='tap'&&k.heat)return 3;return 2}
function advance(s,score){const j=s.job;if(!j)return;j.scores.push(score);const steps=recipeOf(j.d);if(j.si+1<steps.length){enterStep(j,j.si+1);R.tv++}else{const ch=chefHandles(s);if(ch&&!j.plating){/* a chef carries it to the pass and plates it there (finishJob runs when the plate is down) */j.plating={t:0,dur:.7+chefDelay(ch)*.6,x:null};j.step=null;R.tv++}else finishJob(s)}}
function finishJob(s){const j=s.job;if(!j)return;const fin=DISH(j.d).fin;if(fin)for(const f of fin)if(!j.adds.includes(f))j.adds.push(f);const avg=j.scores.length?j.scores.reduce((a,b)=>a+b,0)/j.scores.length:1;const q=avg>=.88?'P':avg>=.68?'G':'O';if(R.holdSlot===s)R.holdSlot=null;plate(s,q)}
function checkOver(j){if(j.overStart==null)return;const over=R.t-j.overStart;if(over>j.overLimit){const bad=over>j.overLimit*2;j.scores[j.overIdx]=bad?.4:.72;toast(`${j.overVerb}${bad?'太久了…':'有點過頭'}`)}j.overStart=null}
function startCook(tk,it,silent){if(!R||it.st!=='pending'||isWF(it.d))return false;const st=DISH(it.d).st;const s=R.slots.find(x=>x.type===st&&!x.job&&!x.wf&&!x.broken);if(!s){if(!silent){toast(`${ST_N[st]}都在忙！`);R.slots.filter(x=>x.type===st).forEach(x=>x.flash=1)}return false}
 s.job=newJob(tk,it);it.st='cooking';R.tv++;if(!silent){R.focus=R.slots.indexOf(s);R.focusLock=R.t+1.2;R.panel=true;R.panelT=0;sfx.tap()}coach(3);return true}
function nextPendingFor(type){for(const tk of R.tickets)for(const it of tk.items)if(it.st==='pending'&&!isWF(it.d)&&DISH(it.d).st===type)return{tk,it};return null}
function ingSfx(id){const k=(ING[id]||{}).k;if(id==='egg')sfx.crack();else if(k==='bottle'||k==='carton')sfx.pour();else if(k==='shaker')sfx.shake();else sfx.plop()}
function actIng(s,id){const j=s.job,k=j&&j.step;if(!k||k.t!=='add'||!k.left.length)return;checkOver(j);const ok=k.order?k.left[0]===id:k.left.includes(id);
 if(ok){k.left.splice(k.left.indexOf(id),1);j.adds.push(id);ingSfx(id);s.pop={id,t:0};if(!k.left.length)advance(s,Math.max(0,1-.3*k.mis))}
 else{k.mis++;s.shake=1;sfx.okay();trayFloat(s,k.order&&k.items.includes(id)?'順序不對':'這道菜不用這個','#FF9A7A')}}
function actDose(s){const j=s.job,k=j&&j.step;if(!k||k.t!=='dose')return;checkOver(j);k.cnt++;j.adds.push(k.ing);ingSfx(k.ing);s.pop={id:k.ing,t:0};if(k.cnt>=k.max+3){trayFloat(s,'太多了！','#FFB27A');advance(s,.3)}}
function actDoseDone(s){const j=s.job,k=j&&j.step;if(!k||k.t!=='dose')return;if(!k.cnt){trayFloat(s,'還沒加喔','#FFD27A');return}const off=k.cnt<k.min?k.min-k.cnt:k.cnt>k.max?k.cnt-k.max:0;trayFloat(s,off===0?'剛剛好':k.cnt<k.min?'少了點':'多了點',off===0?'#9ED08A':'#FFB27A');sfx.tap();advance(s,off===0?1:off===1?.7:.4)}
const CUTADD={veg:'vegmix'};
for(const base in SPECIALS){if(CUTADD[base])CUTADD[SPECIALS[base].id]=CUTADD[base]}
function actTap(s){const j=s.job,k=j&&j.step;if(!k||k.t!=='tap')return;checkOver(j);k.taps++;k.last=R.t;s.shake=1;if(k.heat){sfx.stir();j.mix=Math.max(j.mix,Math.min(1,k.taps/k.n))}else{if(j.d==='souffle')sfx.whisk();else sfx.chop()}
 if(k.taps>=k.n){let sc;if(k.heat)sc=k.scorch<.25?1:k.scorch<.5?.8:.55;else{const e=R.t-k.t0;sc=e<k.n*.45?1:e<k.n*.85?.82:.62;j.cut=true;if(CUTADD[j.d])j.adds.push(CUTADD[j.d])}advance(s,sc)}}
function actZone(s){const j=s.job,k=j&&j.step;if(!k||k.t!=='zone')return;checkOver(j);if(k.p<.25){trayFloat(s,'還太早！','#FFD27A');return}
 j.lastZone=k.p;
 const dd=Math.abs(k.p-k.z.c);const sc=k.p>=1?.5:dd<=k.z.w?1:dd<=k.z.g?.8:.5;if(k.verb==='翻面'){j.sear[j.side]=k.p;j.side=1-j.side;j.lastZone=0;s.flipT=.42;sfx.flip()}else sfx.tap();
 trayFloat(s,sc===1?'完美！':sc>=.8?'不錯':k.p<k.z.c?'有點生':'有點過',sc===1?'#FFE38A':sc>=.8?'#9ED08A':'#FFB27A');advance(s,sc)}
function holdStart(s){const j=s.job,k=j&&j.step;if(!k||k.t!=='hold')return;checkOver(j);k.hold=true;k.holdT=0;R.holdSlot=s}
function applyHold(j,k){const v=Math.min(1,k.level);switch(k.ing){case'beans':j.grind=v;break;case'milk':j.foam=v;break;case'soda':case'custard':case'cheesebatter':case'whites':j.fill=v;break;case'caramel':j.car=v;break;case'cream':j.cream=v;break;case'stock':j.stock=v;break;case'butter':j.butter=v;break;default:j.sauce=v;j.sauceC=(ING[k.ing]||{}).c||'#8A4A2A'}if(!j.adds.includes(k.ing))j.adds.push(k.ing)}
function holdEnd(){const s=R&&R.holdSlot;if(!s)return;R.holdSlot=null;const j=s.job,k=j&&j.step;if(!k||k.t!=='hold'||!k.hold)return;k.hold=false;if(k.level<.04)return;let sc;
 if(k.level>=1){sc=.2;trayFloat(s,'溢出來了！','#E0654A')}else if(k.level>=k.a&&k.level<=k.b){sc=1;trayFloat(s,'剛剛好','#9ED08A')}else if(k.level>=k.a-.08&&k.level<=k.b+.08){sc=.75;trayFloat(s,k.level<k.a?'少了一點':'多了一點','#FFD27A')}else{sc=.45;trayFloat(s,k.level<k.a?'太少了':'太多了','#FFB27A')}
 applyHold(j,k);advance(s,sc)}
function updJob(s,dt){const j=s.job,k=j.step;if(!k)return;const sp=dishSpeed(j.d,s.type);
 if(chefAuto(s,dt))return;
 const hdt=(R.speed||1)>1.5?dt*1.5/R.speed:dt;   /* the hand-timing clock (see SPEEDS) */

 switch(k.t){
 case'wait':k.p+=dt*sp/k.time;j.wait=Math.min(1,k.p);if(k.anim==='stir'){j.mix=Math.max(j.mix,Math.min(1,k.p));k.wt=(k.wt||0)+dt;if(k.wt>.3){k.wt=0;s.shake=.5}}if(k.p>=1){sfx.ding();if(k.over){j.overStart=R.t;j.overLimit=k.over;j.overIdx=j.scores.length;j.overVerb=k.verb}advance(s,1)}break;
 case'zone':k.p=Math.min(1.5,k.p+hdt*sp/k.time);break;
 case'work':{if(chefHandles(s)&&!cookPresent(s))break;k.p+=dt*sp/k.time;k.taps=Math.min(k.n,Math.floor(k.p*k.n));k.wt+=dt;if(k.wt>.18){k.wt=0;s.shake=.8;if(Math.random()<.45)(k.board?sfx.chop():sfx.stir())}if(!k.board)j.mix=Math.max(j.mix,Math.min(1,k.p));
  if(k.p>=1){j.cut=true;if(k.slice)j.sliced=true;if(k.board&&CUTADD[j.d]&&!j.adds.includes(CUTADD[j.d]))j.adds.push(CUTADD[j.d]);advance(s,1)}break}
 case'tap':if(k.heat){if(R.t-k.last>.85)k.scorch+=hdt*.3/(1+.12*(S.eq.pan-1))*(S.day<=2?.6:1);else k.scorch=Math.max(0,k.scorch-hdt*.04);}break;
 case'hold':if(k.hold){k.holdT=(k.holdT||0)+hdt;if(k.holdT>1.3/k.rate+1.5){holdEnd();break}k.level+=hdt*k.rate;s.ht=(s.ht||0)+dt;if(s.ht>.13){s.ht=0;k.ing==='beans'?sfx.grind():k.ing==='milk'?sfx.steam():sfx.pour()}if(k.level>=1.04)holdEnd()}break}}
function addXP(d,n){const before=mLv(d);S.xp[d]=(S.xp[d]||0)+n;const after=mLv(d);if(after>before){toast(`熟練度提升：${DISH(d).n} LV${after}`);if(d==='duck'&&after>=5)ach('duck')}}
function plate(s,q){const j=s.job;s.job=null;const it=j.it;if(!R.tickets.includes(j.tk))return;it.st='ready';it.q=q;it.byJill=!j.chef;R.tv++;if(DISH(j.d).special&&!S.firstSpecial){S.firstSpecial=S.day;const px=j.plating&&j.plating.x||200;memo('firstspecial',px,KY.passTop+6,{d:dishName(j.d),room:'kitchen'});logLine('',`第一盤${dishName(j.d)}從出菜口出去了。`,'e')}
 addXP(it.d,q==='P'?2:1);R.st.q[q]++;trayFloat(s,QN[q],q==='P'?'#FFD95A':q==='G'?'#9ED08A':q==='O'?'#E6D3B0':'#E0654A');
 if(q==='P'){R.st.perfect++;R.streak++;/* rc8.3 (the player: 「可以不要一直跳出perfect擋住選區嗎」): no banner across the screen — the tray's own PERFECT, its sparkle and its sound */sfx.perfect();burst('tray',s,'#FFE38A');if(!S.achievements.first)ach('first')}
 else{R.streak=0;if(q==='G')sfx.good();else sfx.okay()}
 coach(4)}
/* ON FIRE (2026-10-10, the user: 「中後期約 75% 的晚上觸發，已經太頻繁，失去特殊感。調整目標為：一般成熟餐廳在正常經營情況下，約 25%–35% 的
   營業夜晚觸發。仍應由料理品質、團隊表現及經營狀態決定，不要改成與玩家表現無關的純隨機抽籤。Jill 的主廚優勢應保留。」): it was five Perfect
   portions in a row, and every dish of the new kitchen is Perfect — 13 to 16 fires a night, three quarters of every evening's time.
   Now the floor earns it: a run of tables served fast and Perfect while the room is busy. A table whose whole order reaches it
   within FIRE_FAST seconds of sitting down adds to the run — one and a half when Jill cooked for it (the head chef's hand), its
   dishes all Perfect, and only while at least FIRE_BUSY of the tables are taken; a table kept waiting past FIRE_SLOW, a dish
   that is not Perfect or a guest walking out angry ends the run. FIRE_RUN lights it, once a night. No random draw. */
