/* how well the place knows a regular: 0 stranger, .5 眼熟 (2+ visits), 1 熟客 (4+), 2 老客人 (12+) */
function regTier(v){return v>=12?2:v>=4?1:v>=2?.5:0}
/* ---- what the place has learned about a regular: where they sit, what they order, what happened. No meters: this is
   memory, and the game reads it back as habits (a usual table, a usual order) and as a few lines in the journal. ---- */
function regMem(id){S.regMem=S.regMem||{};return S.regMem[id]=S.regMem[id]||{seats:{},orders:{},facts:[],flags:{},last:{}}}
/* everyone at a regular's table who is a regular (a couple = two people); the group name for two; a fact for all of them */
/* the name on the floor by a seated regular (one per person of a couple). Dylan's is not permanent — his silhouette is
   his label (v2.2 Q+); the name shows for a moment when he is tapped or speaks. */
function floorTag(g,k){if(g.reg==='dylan')return k===0&&(S.regulars.dylan||0)>=1&&g.tagT&&R&&g.tagT>R.t?'Dylan':null;const id=regsOf(g)[k];if(id&&REG_BY[id]&&(S.regulars[id]||0)>=1){const n=REG_BY[id].n;return n.length>5?n.slice(0,5):n}return null}
function regsOf(g){return g&&g.regs&&g.regs.length?g.regs:(g&&g.reg?[g.reg]:[])}
function pairName(ids){return ids.map(i=>REG_BY[i]?REG_BY[i].n:i).join('與')}
function regFactG(g,txt){for(const id of regsOf(g))if(id!=='dylan')regFact(id,txt)}
/* who speaks for a group: the person asked for, else — for two — one of them; a couple's lines show both faces */
function speakerOf(g,o){const ids=regsOf(g);if(o&&o.who&&ids.includes(o.who))return o.who;if(ids.length>1)return pick(ids);return g.reg}
/* ================= v2.2 U: world memory =================
   What happened in the restaurant is remembered by the people in it and comes up again later — days after, once,
   not every visit: a regular who sits down in the side room a week after the wall came down; someone who remembers
   the day it stormed; the first special; the record day. Each memory has a source (a day already in the save), a
   window (how many days later it may surface), a low chance per visit, and who says it. Nothing new is recorded for
   it: it reads the days the game already keeps. */
