/* the news before opening: her last nights */
function linNewsHTML(){const d=linLast();if(!d||fact('lin_closed')||loungeLv())return'';const left=d-S.day;if(left>3||left<0)return'';return`<div class="event kent quiet"><b>${left?`隔壁｜Madame Lin 的店再開 ${left} 晚`:'今晚｜隔壁 Madame Lin 的店，最後一晚'}</b><span>${left?'她做到月底。':'明天起，隔壁的門會關著。'}</span></div>`}
/* the tasting: one high-level choice for the player — which way the pairings lean — with no right answer */
function tastingChoice(){if(!R||!R.tasting)return;paused=true;sub='tasting';show(`<div class="modal"><div class="eyebrow">試酒的晚上</div><h2>今晚的酒要往哪邊走？</h2><p>Ken 帶了六瓶來。只有今晚，只有幾桌。沒有標準答案——只是 Jill 想怎麼做。</p><div class="stack"><button class="btn primary" data-act="tastingDir" data-k="food">跟著菜走 <small>每一杯配一道菜，安靜地放在旁邊</small></button><button class="btn primary" data-act="tastingDir" data-k="people">跟著人走 <small>問客人今天想喝什麼，再挑</small></button></div></div>`,'dim')}
function tastingDir(k){if(!R||!R.tasting)return;R.tasting.dir=k;factSet('tasting_dir_'+k);hideScreen();sub=null;paused=false;noteLine(k==='food'?'今晚每一杯都配著菜出去。':'今晚 Ken 先問人，再倒酒。');jillSay(k==='food'?'那就跟著菜。':'那就問他們。',{with:'named:'+KEN})}
/* during the tasting, a few tables get a glass with the meal — counted, remembered, photographed once */
function tastingServe(g){if(!R||!R.tasting||!R.tasting.dir||!g||g.table==null||R.tasting.n>=8||g.tasted)return;if(Math.random()>.6)return;g.tasted=1;R.tasting.n++;const t=R.tables[g.table];addFloat(t.x,t.y-54,'一杯',"#E8C6A0",0,t.room);catCheer(g,.06);for(const id of storyIdsOf(g))factSet('tasted_'+id,true);
 if(R.tasting.n===3){memo('tasting',t.x,t.y-8,{g:g.name,subj:[{x:t.x-30,y:t.y},{x:t.x+30,y:t.y}],room:t.room})}
 if(Math.random()<.35&&canChat('tasting',40,3))quote(g,pickT(['這杯跟這道很搭。','今天有酒？','這樣吃比較像在過節。']))}
/* the user, 2026-10-06: Lounge I is 《看看》 + 評分 4.0 + $50,000 — 「Lounge I 的定位是 content unlock，不應該因為高額資金門檻把大量
   已完成內容一起延後」; the heavier steps are II ($80,000) and III ($150,000) — no level for either (the user, 2026-10-07: rooms of the business, never a story's door). Her last night is her story, never a wait. */
const LOUNGE_PROJ=[
 {lv:1,n:'Lounge I — 小酒吧',cost:50000,need:0,d:'隔壁 Madame Lin 的店：簽約以後改裝兩天，就是 Jill’s Kitchen — The Lounge。吧台留在原來的位置，六個吧台位、三張小桌、一面放酒的牆；跟主廳不打通，菜從後場的廚房送過去。開了以後，吃完飯的人可以留下來，等位子的人可以先坐吧台。Evan 留下來當首席調酒師，開幕那天就在吧台後面，不用招募；Lounge 的人有自己的名單，沈晴（調酒師）、阿拓（Bar Food 料理員，在廚房）可以再請，不佔餐廳的名額。',done:'吧台的燈亮了。牆上有酒，桌上有杯子，Evan 已經站在吧台後面——隔壁現在叫 The Lounge。',jill:'開門吧。',unlock:['Evan，首席調酒師（從今晚起就在吧台）','Lounge 名單：沈晴、阿拓（員工 › Lounge 名單）','Lounge 外場（工作分配）','Lounge 的小食（菜單）']},
 {lv:2,n:'Lounge II — 酒吧沙發廳',cost:80000,need:0,d:'吧台加長、轉成 L 型（調酒師在 L 裡面，九個位子）；多一張小桌、一組四人沙發；一座有燈的酒櫃，酒單全開（五種）。Lounge 名單多兩位：安安（Lounge 外場）、許葳（Lounge 清潔）。',done:'吧台加長了，沙發進來了。酒櫃的燈在牆上亮著。',jill:'現在像個真的晚上了。',unlock:['Lounge 名單：安安、許葳','四人沙發座','酒單五種']},
 {lv:3,n:'Lounge III — 安靜的角落',cost:150000,need:0,d:'最裡面隔出一個安靜的角落：兩張扶手椅、一盞落地燈；酒牆多一層；適合說話的位子。',done:'角落的燈亮了。有人會在那裡坐到很晚。',jill:'留一個地方給說話的人。',unlock:['安靜角落（兩位）','酒牆第三層']},
];
function loungeNext(){const lv=loungeLv();return LOUNGE_PROJ.find(p=>p.lv===lv+1)||null}
/* rc8 §12–§15, the user 2026-10-06 and 2026-10-07: the card before The Lounge — after 《看看》 it needs only the money
   ($50,000): no level, no rating (「人物故事決定一個機會何時出現；錢決定玩家何時有能力把機會變成實際空間。」); then the signing
   and the work. No 「接下隔壁」, no 「再想想」, and no waiting for her last night (signed before it, the evening before the
   signing is her last: linSignPay) */
function linWorksCard(money,btn){const Q=LOUNGE_PROJ[0],LP=S.loungeProj||{};let act='',bar=false;
 if(LP.state==='signing')act=`<span class="muted">${LP.paid===S.day&&!LP.paidPrep?'明天':'今天'}開店前，Jill 去隔壁簽約</span>`;
 else if(LP.state==='reno')act=`<span class="muted">改裝中・Day ${LP.open} 開幕</span>`;
 else{act=btn(Q.cost,'linSign','','簽約・開工')+(money<Q.cost?`<span class="muted" style="font-size:11.5px">還差 ${fmt(Q.cost-money)}</span>`:'');bar=money<Q.cost}
 const pct=Math.min(100,Math.round(money/Q.cost*100));
 return`<div class="item lin-card"><img alt="" src="${iconURL('loungebar')}"><div class="nm">${Q.n}</div><div class="d">${Q.d}</div><div class="act">${act}</div>${bar?`<div class="gb"><i style="width:${pct}%"></i></div>`:''}</div>`}
function secLounge(money,btn){const P=loungeNext();if(!fact('lounge_project')&&!loungeLv())return'';const LP=S.loungeProj||{};
 let body=`<div class="nm" style="font-weight:800;font-size:15px;margin:14px 0 2px">Lounge</div><p class="muted" style="font-size:12px;margin:0 0 6px">${loungeLv()?`Lounge ${['','I','II','III'][loungeLv()]} 開著。`:LP.state==='reno'?`隔壁在改裝，Day ${LP.open} 開幕。`:LP.state==='signing'?'錢付了，鑰匙還沒拿。':fact('lin_closed')?'Madame Lin 的店關了。Jill 決定接。':'隔壁 Madame Lin 的店。Jill 決定接。'}</p>`;
 if(!loungeLv())body+=linWorksCard(money,btn);
 for(const Q of LOUNGE_PROJ){const on=loungeLv()>=Q.lv;const next=P&&P.lv===Q.lv&&Q.lv>1;if(!on&&!next)continue;const ok=S.level>=Q.need;const pct=Math.min(100,Math.round(money/Q.cost*100));
  body+=`<div class="item ${on?'done':''}"><img alt="" src="${iconURL('loungebar')}"><div class="nm">${Q.n} ${on?'<span class="tier t1">已完工</span>':''}</div><div class="d">${on?Q.done:Q.d}</div>${on?'':`<div class="act">${ok?btn(Q.cost,'buyLounge',`data-k="${Q.lv}"`,'開工'):`<span class="muted">需要擴建到 ${LEVELS[Q.need-1].n}</span>`}${ok&&money<Q.cost?`<span class="muted" style="font-size:11.5px">還差 ${fmt(Q.cost-money)}</span>`:''}</div>${ok&&money<Q.cost?`<div class="gb"><i style="width:${pct}%"></i></div>`:''}`}</div>`}
 if(loungeLv()){const PN=DREAMS.find(x=>x.k==='piano');if(PN)body+=dreamCardHTML(PN,btn)}   /* the user, 2026-10-07: the piano with The Lounge */
 body+=secChefNight();   /* rc7.6 */
 return body}
function loungeBuild(lv){const Q=LOUNGE_PROJ.find(p=>p.lv===lv);S.rooms.lounge=lv;S.newRooms=S.newRooms||{};if(lv===1){S.newRooms.lounge=S.day;S.crew=S.crew||[];if(!S.crew.some(m=>m.name==='Evan'&&m.role==='bartender'))S.crew.push(evanNew(S.day))}/* rc7.7: Evan, behind the bar from the first night */S.newRooms['lounge'+lv]=S.day;factSet('lounge_built_'+lv);S.loungeProj=S.loungeProj||{};S.loungeProj.state='built';for(const d of barDishes())if(!DISHES[d].rd)unlockDish(d);/* rc7.4: a researched dish (the pizza) is never unlocked by building the room */if(lv===1)ach('lounge1');else if(lv===2)ach('lounge2');else ach('lounge3');save();IDLE=null;bg=null;for(const kk in BGC)delete BGC[kk];return Q}
/* II and III from the works page; I comes through the signing (linSignPay → 《簽約》 → two days → loungeOpenNow). A test may still build I directly. */
function buyLounge(lv){const Q=LOUNGE_PROJ.find(p=>p.lv===lv);if(!Q||loungeLv()!==lv-1||S.money<Q.cost||S.level<Q.need)return false;S.money-=Q.cost;loungeBuild(lv);projectReveal({k:'lounge',n:Q.n,done:Q.done,jill:Q.jill,unlock:Q.unlock,room:'lounge'});return true}
/* ================= v2.3 Phase 6: people learn places — station and wine familiarity, tenure, the pantry =================
   Coarse and lightweight: days worked in a place (m.fam[area]) and glasses handled (m.wine), counted at the end of a
   day. Familiarity transfers — an experienced server is not a beginner in the Lounge, only slower on the first shifts
   and asking where table three is; a bartender who works the halls learns them the same way. No tree, no points. */
const FAM_N=[[0,'新'],[3,'熟悉'],[10,'熟練']];
function famLabel(n){let l=FAM_N[0][1];for(const [d,t] of FAM_N)if((n||0)>=d)l=t;return l}
function famOfArea(m,area){return(m.fam&&m.fam[area])||0}
function crewAreas(m){const a=[];if(m.role==='chef')a.push('kitchen');if(m.role==='waiter'){a.push('main');if(projOn('side'))a.push('side');if(waiterDuties(m).lounge&&loungeLv())a.push('lounge')}if(m.role==='bartender'&&m.duty==='lbar')a.push('lounge');if(m.role==='cleaner'){a.push('main');if(projOn('side'))a.push('side');if(loungeLv())a.push('lounge')}return a}
function crewDayDone(){staffEnsembleCheck();for(const m of S.crew||[]){if(!m.since){m.since=S.day;m.sinceLegacy=1}m.days=(m.days||0)+1;m.fam=m.fam||{};for(const a of crewAreas(m))m.fam[a]=(m.fam[a]||0)+1;if(m.role==='waiter'&&m.wineDay){m.wine=(m.wine||0)+m.wineDay;m.wineDay=0}}}
function wineLabel(n){return n>=40?'自在':n>=10?'基本':'還不熟'}
/* v2.4 rc6 (10:40): the floor that knows its wine sells a glass with dinner more often — each waiter at ease with it
   (by the glasses carried, or the course) adds a little, at most a third */
const WINE_COURSE=12000;   /* a wine course for one waiter */
function wineFloorBoost(){const n=(S.crew||[]).filter(m=>m.role==='waiter'&&(m.wine||0)>=40&&(!R||crewHere(m))).length;return 1+Math.min(.33,n*.08)}
const AREA_N={main:'主廳',side:'側廳',lounge:'Lounge',kitchen:'廚房'};
function famLine(m){const areas=crewAreas(m);const known=areas.filter(a=>famOfArea(m,a)>=3).map(a=>AREA_N[a]);const learning=areas.filter(a=>famOfArea(m,a)<3).map(a=>AREA_N[a]);const parts=[];if(known.length)parts.push('熟悉：'+known.join('、'));if(learning.length)parts.push('正在熟悉：'+learning.join('、'));if(m.role==='waiter'&&loungeLv())parts.push('酒：'+wineLabel(m.wine||0));if(m.role==='bartender'&&m.wine)parts.push(`倒過 ${m.wine} 杯`);return parts.join('・')}
function tenureLine(m){if(crewLegacy(m))return`${tenure(m)}（v2.3 以前就在）`;const n=m.days||0;return n>=1?`在店 ${n} 天`:m.core?((m.since||1)>1?'今天起正式上班':'開店第一天就在'):'今天剛來'}   /* 秀琴阿姨 is on the staff from the first day (2026-10-10); an older save she joins later counts from that day */   /* v2.4 A2: the old crew's counted days are not their history */
/* a first Lounge shift is slower, and someone asks where table three is — once; a veteran answers a newcomer, once */
function loungeShiftMul(m){if(m.role!=='waiter')return 1;const f=famOfArea(m,'lounge');return f>=10?.92:f>=3?1:1.25}
function firstShiftLine(m,t){if(!R||!t||!t.lounge||m.role!=='waiter'||famOfArea(m,'lounge')>=3||m.askedLg)return;m.askedLg=1;const vet=(S.crew||[]).find(q=>q!==m&&q.role==='waiter'&&famOfArea(q,'lounge')>=10)||(S.crew||[]).find(q=>q.role==='bartender'&&q.duty==='lbar');
 staffSay(m,pickT(['這杯是哪桌？','三號是哪邊？','Lounge 的三號在哪？']),undefined,t.group||undefined);if(vet)speakLater(()=>{if(R&&phase==='service')staffSay(vet,famOfArea(vet,'lounge')>=10?'靠牆第二桌。':'三號。',undefined,t.group||undefined)},1600);relSet('s:'+m.id,vet?'s:'+vet.id:'jill','helped');if(vet)relSet('s:'+vet.id,'s:'+m.id,'helpedBy')}
/* 阿拓's hand: bar food, faster and surer; the pantry's fryer gives every chef a little of it */
function barCookMul(m,d){const D=DISH(d);if(!D||!D.bar)return 1;let k=1;if(m&&m.name==='阿拓')k*=.7;if(opsLv('pantry'))k*=.8;return k}
/* ================= v2.3 Phase 7: people who know each other — the authored arcs, on the foundation =================
   Nothing here is a meter or a stage the player sees. Each arc is a few events on the same arbiter: hard requirements
   read from real history (facts written by things that happened), one presentation per event with fallbacks, and a
   consequence that changes a small behaviour afterwards (where someone sits, who is waited for, what is brought
   before it is asked for). Romance exists only for the two authored pairs (ROMANCE_OK); the generic facts (co-presence,
   waiting, leaving together) are friendship facts and Ken × Monsieur 杜 collect them all without ever being a couple. */
function crewByName(n){return(S.crew||[]).find(m=>m.name===n)||null}
function crewId(n){const m=crewByName(n);return m?'s:'+m.id:null}
function whoName(id){if(!id)return'';if(id==='jill')return'Jill';if(id==='dylan')return'Dylan';if(id.startsWith('n:'))return id.slice(2);if(id.startsWith('s:')){const m=(S.crew||[]).find(q=>'s:'+q.id===id);return m?m.name:'員工'}if(REG_BY[id])return REG_BY[id].n;const C=CAT_DEF.find(x=>x.id===id);return C?catName(C):id}
const SEATED_ST=['toTable','reading','order','wait','eat','check'];   /* toTable: just seated, walking over — already at the table for every purpose here */
function seatedId(id){return R&&R.groups.find(g=>g.table!=null&&!g.gone&&SEATED_ST.includes(g.state)&&storyIdsOf(g).includes(id))||null}
function presentId(id){return R&&R.groups.find(g=>!g.gone&&g.state!=='leave'&&storyIdsOf(g).includes(id))||null}
/* audit N06 (2026-10-06): who is still in the restaurant when it closes — here now, or gone only after the doors closed and
   not with someone (「…一起走了。」). 「打烊後，Ken 沒有走。」 asked only whether he came today, so it followed 「品酒師 Ken 和
   Monsieur 杜 一起走了。」 by an hour. */
function stillHere(id){if(!R)return false;if(presentId(id))return true;const L=(R.leftAt||{})[id];return !!(L&&L.closed&&!L.together&&!(R.leftTog&&R.leftTog[id]))}
/* ================= the floor (audit N04, W3-02; 2026-10-06) =================
   The room's speech runs on the service clock: a story's panel or the pause sheet holds it with the rest of the room (it
   went on underneath, unseen — Ken and 杜's 「這支太甜了。」 under the photo). And one exchange speaks at a time: an exchange
   is what one moment sets going — a beat's code, Jill's greeting and its answer, 「還可以嗎？」 and the reply, a treat and
   its thanks. One that begins while another is still being said waits for that one's last line, so a question is answered
   by its own answer (「Mia，今天想吃什麼？」 was answered 「第二層左邊。」, another exchange's). Small talk is left out while
   the floor is taken. Before opening and after the service the wall clock is kept (nobody else is talking then). */
const FLOOR_GAP=1.2;   /* service-clock seconds of quiet after an exchange's last line */
let TALK=null;         /* the exchange being set going right now: {max} — when its last line comes */
function floorBusy(){return !!(R&&phase==='service'&&R.floorUntil!=null&&R.t<R.floorUntil)}
function svcAt(sec,fn,cx){if(!R)return;const q=R.talkq=R.talkq||[];q.push({t:R.t+sec,n:(R.talkN=(R.talkN||0)+1),fn,cx:cx||null})}
function talkUpd(){const q=R.talkq;if(!q||!q.length)return;const due=q.filter(x=>R.t>=x.t);if(!due.length)return;R.talkq=q.filter(x=>R.t<x.t);due.sort((a,b)=>a.t-b.t||a.n-b.n);for(const x of due){try{x.fn()}catch(e){console.warn('[talk]',e)}}}
function floorFlush(){if(!R)return;R.floorUntil=null;for(let i=0;i<6&&R.talkq&&R.talkq.length;i++){const q=R.talkq;R.talkq=[];for(const x of q.sort((a,b)=>a.t-b.t||a.n-b.n)){try{x.fn()}catch(e){console.warn('[talk]',e)}}}}   /* the evening ends: what was still waiting to be said is said (or finds nobody) */
/* a line of the room, ms from now (at 1×, as the game's lines were written); fast: the tests' __fastSay says it at once */
function speakLater(fn,ms,fast){if(fast&&window.__fastSay){fn();return}const cx=SCX;
 if(!R||phase!=='service'||(cx&&cx.authored&&shOn())){setTimeout(fn,ms);return}   /* before opening, after the service, or a held beat: its panel brings its lines as they are read */
 const sec=Math.max(0,+ms||0)/1000*simSpeed();svcAt(sec,cx?()=>shRun(cx,fn):fn,cx);
 if(TALK)TALK.max=Math.max(TALK.max,sec);else R.floorUntil=Math.max(R.floorUntil||0,R.t+sec+FLOOR_GAP)}
/* an exchange: now if the floor is free, else after the one being said */
function talk(fn,now){if(!R||phase!=='service'||window.__fastSay||(SCX&&SCX.authored&&shOn())){fn();return}
 if(!now&&floorBusy()&&!TALK){svcAt(R.floorUntil-R.t+.05,()=>talk(fn));return}
 if(TALK){fn();return}   /* inside an exchange already: one exchange */
 TALK={max:0};try{fn()}finally{const T=TALK;TALK=null;if(R)R.floorUntil=R.t+T.max+FLOOR_GAP}}
function later(fn,ms){speakLater(fn,ms,true)}   /* tests read the lines at once (__fastSay) */
function sayG(g,txt,ms,o){later(()=>{if(R&&phase==='service'&&R.groups.includes(g)&&!g.gone)quote(g,txt,o)},ms||400)}
function sayS(m,txt,ms,tone){later(()=>{if(R&&phase==='service'&&m&&(S.crew||[]).includes(m)&&crewHere(m))staffSay(m,txt,tone)},ms||400)}
/* ---- the romance whitelist: the only pairs whose history may ever be read as more than friendship ---- */
const ROMANCE_OK=[pairKey('sophie','mia'),'s:沈晴|s:阿拓'];
function romancePair(a,b){const k=pairKey(a,b);if(k===ROMANCE_OK[0])return true;/* the staff pair is by name, whoever holds the ids */const na=whoName(a),nb=whoName(b);return(na==='沈晴'&&nb==='阿拓')||(na==='阿拓'&&nb==='沈晴')}
function romanticEligible(a,b){if(!romancePair(a,b))return false;const f=rel(a,b);const n=k=>f[k]?f[k].n:0;/* qualitative: an active choice, space made, food shared, waiting — never a count of evenings */return n('choseNear')>=1&&n('madeSpace')>=1&&n('sharedFood')>=1&&n('waitedFor')>=1}
/* ---- pairs whose members drift toward each other in a room (friends and the authored pair alike) ---- */
const KEN_ID='n:'+KEN,DU_ID='n:'+DU;
const PAIRS=[
 {a:'sophie',b:'mia',near:()=>fact('sm_b'),linger:()=>fact('sm_e'),leave:()=>fact('sm_f')},
 {a:KEN_ID,b:DU_ID,near:()=>relN(KEN_ID,DU_ID,'sharedTable')>=1||kdNightNow(),linger:()=>fact('kd_usual'),leave:()=>fact('kd_usual')},
];
function pairOf(id){for(const P of PAIRS)if(P.a===id||P.b===id)return{P,me:id,other:P.a===id?P.b:P.a};return null}
function pairFor(g){for(const id of storyIdsOf(g)){const p=pairOf(id);if(p)return p}return null}
/* the free dining table nearest the partner's table, when the pair has reached that point and the partner is seated */
function storyNearTable(g,free){const p=pairFor(g);if(!p||!p.P.near()||free.length<2)return null;const og=seatedId(p.other);if(!og||og.table==null)return null;const ot=R.tables[og.table];if(ot.lounge)return null;const cand=free.filter(t=>(t.room||'main')===(ot.room||'main')&&t.seats>=g.size);if(cand.length<2)return null;cand.sort((x,y)=>Math.hypot(x.x-ot.x,x.y-ot.y)-Math.hypot(y.x-ot.x,y.y-ot.y));
 /* rc8.3 (the player, Day 89: 「sophie mia根本沒有坐在一起」): 「旁邊」 is the table next to hers — the nearest of all the room's tables, not
    the nearest free one wherever it is; else not today */
 const d=t=>Math.hypot(t.x-ot.x,t.y-ot.y);const d0=Math.min(...R.tables.filter(t=>t!==ot&&(t.room||'main')===(ot.room||'main')&&!t.out).map(d));if(!(d(cand[0])<=d0*1.15))return null;
 g.nearPick={i:cand[0].i,other:p.other,alt:cand.length-1};return cand[0]}
/* a stool next to the partner's stool; the held stool (a bag on it) is only for the one it is held for */
function stoolFree(t,g){if(t.tst&&R&&R.kt&&!R.kt.end&&!(g&&g.tasting))return false;if(t.cnr&&R&&R.cn&&!R.cn.end&&!(g&&g.cn))return false;/* rc7.6: the chef's night has the bar *//* rc7: Ken's tasting night — the bar is for the people who came for it */if(!t.hold)return true;if(!stoolHoldValid(t))return true;return storyIdsOf(g).includes(t.hold)}
function stoolHoldValid(t){if(!t.hold)return false;const h=seatedId(t.holdBy);if(!h||h.table==null||R.tables[h.table]!==t.holdOf){t.hold=null;t.holdBy=null;t.holdOf=null;return false}return true}
function storyNearStool(g,free){const p=pairFor(g);if(!p||!p.P.near())return null;const og=seatedId(p.other);if(!og||og.table==null)return null;const ot=R.tables[og.table];if(ot.kind!=='bar')return null;const adj=free.filter(t=>t.kind==='bar'&&Math.abs(t.x-ot.x)<34&&t!==ot);if(!adj.length)return null;g.nearPick={i:adj[0].i,other:p.other,alt:free.length-1};return adj[0]}
function holdStoolFor(g,t){if(!t||t.kind!=='bar'||!R)return;const p=pairFor(g);if(!p||!p.P.near()||!fact('sm_c')&&p.P.a==='sophie')return;if(p.P.a===KEN_ID&&!fact('kd_usual')&&!kdNightNow())return;if(seatedId(p.other))return;const n=loungeTables().find(q=>q.kind==='bar'&&!q.group&&!q.dirty&&!q.claim&&!q.hold&&Math.abs(q.x-t.x)<34&&q!==t);if(!n)return;n.hold=p.other;n.holdBy=p.me;n.holdOf=t;factSet('held_'+p.me,true)}
/* ---- waiting: the meal is over, the partner is on the schedule for later — she stays (once), and only if the partner is really coming ---- */
function partnerLater(id){if(!R||R.closed)return null;for(let i=R.si;i<R.sched.length;i++){const o=R.sched[i];const oid=o.reg?o.reg:o.name&&NAMED[o.name]?'n:'+o.name:null;if(oid===id&&o.t-R.t<110)return o}return null}
function storyLinger(g){if(!R||g.lingered||g.table==null)return false;if(yjWaitsForMom(g))return true;if(R.closed)return false;if(namedId(g)===KEN&&kenSamplesDue()&&!kenNightToday()){g.timer=20;return true}   /* the samples night (audit N06): he has the three bottles with him — he stays till the doors close */if(namedId(g)==='周董'&&!g.zhouStay){const t0=R.tables[g.table];const c=catBy('snow');if(c&&!c.hidden&&(c.st==='sleep'||c.st==='bed')&&(t0.room||'main')==='main'&&Math.hypot(c.x-t0.x,c.y-t0.y)<100){g.zhouStay=1;g.timer=25;JILL_SAY('你不是有事？',600,{with:'named:周董'});sayG(g,'牠在睡。',2000);g.lookT=R.t+3;g.lookCat=c;relSet('n:周董','snow','stayedFor');regFactNamed('周董',`${catName(c.def)}在旁邊睡著，他就沒走。`);return true}}const p=pairFor(g);if(!p||!p.P.linger())return false;if(seatedId(p.other)||presentId(p.other))return false;const o=partnerLater(p.other);if(!o)return false;g.lingered=1;g.lingerFor=p.other;g.timer=Math.max(8,Math.min(120,o.t-R.t+20));
 const t=R.tables[g.table];const bt=t.lounge?(S.crew||[]).find(m=>m.role==='bartender'&&m.duty==='lbar'):null;
 if(bt){sayS(bt,'還要什麼嗎？',600);sayG(g,'不用。',2100)}else if(Math.random()<.6){JILL_SAY('還要什麼嗎？',600);sayG(g,'不用。',2100)}
 noteLine(`${g.name} 吃完了，還坐著。`);return true}
function lingerMet(g){/* the partner sat down: whoever was staying for them has waited */if(!R)return;for(const id of storyIdsOf(g)){for(const o of R.groups){if(o===g||o.gone||o.lingerFor!==id||o.table==null)continue;o.lingerFor=null;o.timer=Math.max(o.timer||0,30);const me=storyIdsOf(o).find(x=>pairOf(x)&&pairOf(x).other===id);if(!me)continue;relSet(me,id,'waitedFor');factSet('waited_'+me);const t=R.tables[o.table];const bt=t.lounge?(S.crew||[]).find(m=>m.role==='bartender'&&m.duty==='lbar'):null;if(bt){noteLine(`${bt.name} 看了一眼，什麼都沒說。`);relSet('s:'+bt.id,me,'sawWait')}else noteLine(`${whoName(me)} 等的人來了。`)}}}
/* ---- leaving together: only when both are really at the end of the evening ---- */
function storyLeaveTogether(g){if(!R||g.leaveWith)return;const p=pairFor(g);if(!p||!p.P.leave())return;if((p.me===KEN_ID||p.other===KEN_ID)&&kenSamplesDue()&&!kenNightToday())return;   /* not on the samples night: Ken stays */const o=seatedId(p.other);if(!o||o===g||o.counted&&o.state==='leave')return;const a=p.me,b=p.other;
 if(o.state==='check'){o.leaveWith=a;collect(o,{});leftTogether(a,b,g,o)}
 else if(o.state==='eat'&&o.timer<40){o.timer=Math.min(o.timer,1.5);R.pairLeave={a,b,t:R.t,g}}}
function leftTogether(a,b,g,o){if(R){R.leftTog=R.leftTog||{};R.leftTog[a]=1;R.leftTog[b]=1}relSet(a,b,'leftTogether');const first=!fact('left_'+pairKey(a,b));factSet('left_'+pairKey(a,b));noteLine(`${whoName(a)} 和 ${whoName(b)} 一起走了。`);
 if(first&&romancePair(a,b))memo('together',DOOR.x+30,DOOR.y+10,{a:whoName(a),b:whoName(b),subj:[g,o],room:'main'});else if(Math.random()<.3)memo('together',DOOR.x+30,DOOR.y+10,{a:whoName(a),b:whoName(b),subj:[g,o],room:'main'});
 if(romancePair(a,b)&&fact('sm_h')&&!story().photos.sophie_mia_leave)storyPhoto('sophie_mia_leave',{a:whoName(a),b:whoName(b)});storyTick('leave',{g,o,a,b})}
function pairLeaveCheck(g){const pl=R&&R.pairLeave;if(!pl)return;if(R.t-pl.t>45){R.pairLeave=null;return}if(storyIdsOf(g).includes(pl.b)){R.pairLeave=null;leftTogether(pl.a,pl.b,pl.g,g)}}
/* ---- arriving together: on the schedule, once the history allows it — two entries, one time, still two people ---- */
function storyScheduleTogether(out){const k=pairKey('sophie','mia');if(!fact('left_'+k))return;const A=out.find(o=>o.reg==='sophie'),B=out.find(o=>o.reg==='mia');if(!A||!B)return;const since=S.day-fact('left_'+k).d;const p=fact('sm_h')?.35:since>=3?.6:0;if(hash('together|'+S.day)%1000>=p*1000)return;const t=Math.min(A.t,B.t);A.t=t;B.t=t+1.5;A.together='sm';B.together='sm'}
/* ---- 周董's 「隨便」: the same things every time; a usual table; the dessert ---- */
function namedTop(name,cat){const h=story().named[name];if(!h||!h.dishes)return null;let best=null,bn=1;for(const d in h.dishes){const D=DISH(d);if(!D||(cat&&D.cat!==cat))continue;if(h.dishes[d]>bn){bn=h.dishes[d];best=d}}return best}
function namedSeat(g,t){const n=namedId(g);if(!n||!t||t.lounge)return;const h=namedHist(n);h.seats=h.seats||{};h.seats[t.i]=(h.seats[t.i]||0)+1}
function namedUsualTable(name){const h=story().named[name];if(!h||!h.seats)return null;let best=null,bn=2;for(const k in h.seats)if(h.seats[k]>bn){bn=h.seats[k];best=+k}return best}
function zhouOrder(ms){const main=namedTop('周董','main'),des=namedTop('周董','dessert'),drink=namedTop('周董','drink');const h=story().named['周董'];if(!h||h.v<3)return null;const out=[];for(const d of[main,drink,des])if(d&&ms.includes(d))out.push(d);return out.length>=2?out:null}
/* ---- Madame Lin sees the room: what is different since her last visit (only what she could have seen) ---- */
const LIN_SEES={ac:{k:()=>opsLv('ac'),q:'冷氣換過了？',n:'空調'},light:{k:()=>S.decor.lights,q:'燈換了。',n:'燈'},side:{k:()=>projOn('side')?1:0,q:'多了一間？',n:'側廳'},terrace:{k:()=>projOn('terrace')?1:0,q:'外面也擺桌子了。',n:'戶外座位'},chairs:{k:()=>S.decor.chairs,q:'椅子換了。',n:'椅子'},dish:{k:()=>opsLv('dish'),q:'廚房那台是新的？',n:'洗碗機'},lounge:{k:()=>0,q:'隔壁的燈亮了。',n:'Lounge'},   /* rc8: the Lounge is her old bar — nothing she would notice from here (kept for the saves that have it) */plants:{k:()=>S.decor.plants,q:'多了植物。',n:'植物'},glass:{k:()=>opsLv('glass'),q:'店面整個換過了。',n:'玻璃店面'}};
function linSnap(){const o={};for(const k in LIN_SEES)o[k]=LIN_SEES[k].k()||0;return o}
function linNoticed(){const h=namedHist('Madame Lin');const prev=h.saw;const now=linSnap();if(!prev){h.saw=now;return null}/* the first time she is only looking */const diff=[];for(const k in now)if(now[k]>(prev[k]||0))diff.push(k);return diff}
/* ---- the cats and the people who come back: who has had which cat near them, often ---- */
function catFamOf(id,cid){const f=rel(id,cid);let n=0;for(const k in f)if(k.startsWith('cat_'))n+=f[k].n;return n}
function knownCatFor(g){const ids=storyIdsOf(g);let best=null;for(const id of ids)for(const C of CAT_DEF){const n=catFamOf(id,C.id);if(n>=4&&(!best||n>best.n))best={id,cid:C.id,n}}return best}
/* ---- the staff who work the Lounge: how each of them notices (Evan quiet, 安安 spatial, 晴 direct) ---- */
function evanOn(){const m=crewByName('Evan');return m&&m.role==='bartender'&&m.duty==='lbar'&&loungeLv()?m:null}
function qingOn(){const m=crewByName('沈晴');return m&&m.role==='bartender'&&m.duty==='lbar'&&loungeLv()&&crewHere(m)?m:null}   /* v2.4 rc6 (12:16): and in today */
function ananOn(){const m=crewByName('安安');return m&&m.role==='waiter'&&waiterDuties(m).lounge&&loungeLv()?m:null}
function tuoOn(){const m=crewByName('阿拓');return m&&m.role==='chef'&&crewHere(m)?m:null}   /* v2.4 rc6 (12:16): and in today — his day off is the absence */
function hugoOn(){return(S.crew||[]).find(m=>m.role==='chef'&&m.name!=='阿拓')||null}
function kenAtBar(){const g=kenAt();return g&&R.tables[g.table].kind==='bar'?g:null}
function duAtBar(){const g=duAt();return g&&R.tables[g.table].kind==='bar'?g:null}
function kdBoth(){const k=kenAtBar(),d=duAtBar();return k&&d&&Math.abs(R.tables[k.table].x-R.tables[d.table].x)<34?{k,d}:null}
