/* ================= v2.4 foundations (docs/v24/AUDIT_AND_PLAN.md §2–§3) =================
   Tenure as a class, one day's story presence, the order the long stories come in, pacing by the fiction's own time,
   the walk-over, and the story illustrations. Nothing here is a second simulation: the arbiter above picks the beats,
   the facts above remember them. */
/* A2: how long someone has been here, as a class — never a date. Whoever was on the crew before v2.3 began counting is
   熟手 unless the player's canon says more (阿珠姐, 秀琴阿姨, 阿德師傅 資深; 小彤 較新, 熟手 after 45 counted days);
   anyone hired since has their counted days: 新 under 10, 熟手 from 10, 資深 from 60. */
const TENURE_CANON={'阿珠姐':'資深','秀琴阿姨':'資深','阿德師傅':'資深','小彤':'較新'};
const TENURE_RANK={'新':0,'較新':1,'熟手':2,'資深':3};
function crewLegacy(m){return !!m&&(!!m.sinceLegacy||m.since==null)}
function tenure(m){if(!m)return'新';const d=m.days||0;if(crewLegacy(m)){const c=TENURE_CANON[m.name];if(c==='較新')return d>=45?'熟手':'較新';return c||'熟手'}return d>=60?'資深':d>=10?'熟手':'新'}
function tenureAtLeast(m,cls){return TENURE_RANK[tenure(m)]>=TENURE_RANK[cls]}
function mostSenior(list){return list.slice().sort((a,b)=>(TENURE_RANK[tenure(b)]-TENURE_RANK[tenure(a)])||((b.days||0)-(a.days||0)))[0]||null}
/* 《第二層左邊》: the cook who knows where everything is — 阿珠姐 when she is in, else the most senior cook here */
function veteranCook(){const here=(S.crew||[]).filter(m=>m.role==='chef'&&crewHere(m)&&(crewLegacy(m)?tenureAtLeast(m,'熟手'):(m.days||0)>=15));return here.find(m=>m.name==='阿珠姐')||mostSenior(here)}
/* A3: story presence for one day, set only by an authored beat — never a rota. off: not in today; late: comes in at a
   point of the service (at: 0–1 of it); left: goes home at a point of the service. Someone who is not here is not drawn
   and does no work; nothing else changes (the day's wage is paid as usual). */
const AWAY_N={off:'今天沒來',late:'晚點到',left:'先走了'};
function crewAwayMap(){const a=story().away;return a&&a.d===S.day?a.m:null}
function crewAwayOf(m){const a=crewAwayMap();return m&&a?a[m.id]||null:null}
function setCrewAway(m,k,at){if(!m||!AWAY_N[k])return;const st=story();if(!st.away||st.away.d!==S.day)st.away={d:S.day,m:{}};st.away.m[m.id]={k,at:at==null?(k==='late'?.3:k==='left'?.7:0):at}}
function serviceFrac(){if(R&&phase==='service'&&R.dur)return R.closing!=null?1:Math.min(1,R.t/R.dur);return phase==='prep'?0:1}
function crewHere(m){const e=crewAwayOf(m);if(!e)return true;if(e.k==='off')return false;const f=serviceFrac();return e.k==='late'?f>=e.at:e.k==='left'?f<e.at:true}
/* someone who is not here (any more): out through the front door if they were in the room, then gone */
function crewAwayUpd(m,dt){const w=R.cw&&R.cw[m.id];if(!w)return;const tk=w.task;if(tk){if(tk.k!=='visit'){if(tk.g&&tk.g.claim===m.id)tk.g.claim=null;if(tk.t&&tk.t.claim===m.id)tk.t.claim=null;if(tk.tk&&tk.tk.claim===m.id)tk.tk.claim=null}w.task=null}
 handsDrop(w);ddDeposit(w);if(ddWashOf(m.id))ddWashEnd(w,m.id);w.next=null;w.nextQ=null;w.arriving=0;w.phone=0;w.tx=FR.exit.x;w.ty=FR.exit.y;w.troom='front';
 if(stepTo(w,(115+15*m.lv)*dt))delete R.cw[m.id];else{w.moving=true;w.step+=dt*12}}
/* a cook who is not here (any more): out of the kitchen door, then gone */
/* the next point a cook in the kitchen walks to on the way to (x, y): a corner round the counters (via), or (x, y) itself */
function kWay(a,x,y){const w=obsNext(a,'kitchen',x,y);return w&&Math.hypot(w.x-a.x,w.y-a.y)>1?{x:w.x,y:w.y,via:1}:{x,y,via:0}}
function cookAwayUpd(m,dt){const a=R.ck&&R.ck[m.id];if(!a)return;const d0=KR.door,w0=kWay(a,d0.x,d0.y),dx=w0.x-a.x,dy=w0.y-a.y,dd=Math.hypot(dx,dy),v=(200+16*m.lv)*dt;a.idle=null;if(!w0.via&&dd<=v){delete R.ck[m.id];return}if(dd<=v){a.x=w0.x;a.y=w0.y}else{a.x+=dx/dd*v;a.y+=dy/dd*v}a.moving=true;a.step+=dt*13;if(Math.abs(dx)>.5)a.face=dx>0?1:-1;a.beat={kind:'idle',x:d0.x,y:d0.y}}
/* the walk-over: a cleaner or a server walks to a table for a story exchange, stands there while it plays, then goes
   back to work — the same walk as clearing a table. A cook never does this. o: {then: called on arrival, dur: seconds
   she stays once the exchange is over}. False when she cannot (not here, not in the room yet). */
function crewSprite(m){if(!R||!m)return null;return(R.cw&&R.cw[m.id])||(m.helper&&R.xqh)||null}
function staffWalkOver(m,t,o){if(!R||phase!=='service'||!m||!t||m.role==='chef'||!crewHere(m))return false;const w=crewSprite(m);if(!w||w.arriving)return false;o=o||{};if(SCX&&o.then){const cx=SCX,f=o.then;o=Object.assign({},o,{then:(...a)=>shRun(cx,()=>f(...a))})}
 return visitQueue(w,{k:'visit',t,g:t.group||null,x:t.x+(t.x<200?-24:24),y:t.y+22,room:t.room||'main',dur:o.dur==null?1.5:o.dur,then:o.then||null})}
function visitQueue(w,v){if(w.next||(w.task&&w.task.k==='visit')){(w.nextQ=w.nextQ||[]).push(v)}else w.next=v;return true}
function walkingOver(m){const w=crewSprite(m);return !!(w&&((w.task&&w.task.k==='visit')||(w.next&&w.next.k==='visit')||(w.nextQ&&w.nextQ.length)))}
/* ---- v2.4 pacing (docs/v24/pacing_rule_correction): one major beat a day is the arbiter's own cap, shared with every
   story; there is no other gap between beats or between stories. A stage waits only as long as its fiction needs —
   its `gap` in days after the stage before it. Nothing fires at the very start of the first day this version is
   played (no load-time dump). ---- */
function v24(){const st=story();const v=st.v24=st.v24||{};if(v.first==null)v.first=S.day;v.dorm=v.dorm||{};v.wait=v.wait||{};v.wx=v.wx||{};return v}
function v24Fresh(at){return S.day===v24().first&&(at==='daystart'||!R||R.t<20)}
function stageDay(k){const f=fact(k);return f?f.d:null}
function stageGap(prev,gap){if(!prev)return true;const d=stageDay(prev);return d!=null&&S.day-d>=(gap||0)}
function v24Wx(w){const v=v24();if(w)v.wx[S.day]=w;for(const d in v.wx)if(+d<S.day-12)delete v.wx[d]}
function rainedWithin(n){const v=v24();for(let d=S.day-n;d<=S.day;d++){const w=v.wx[d];if(w==='rain'||w==='storm')return true}return false}
/* the order the long stories come in (implementation pass B; pacing correction; the player's 10:25 correction): two
   chains that do not wait for each other. 怡君 → 《那面牆》: the wall opens when 怡君's story has ended, plus its settle
   days. The Second Floor → the Staff Room → the Private Dining Room: the floor opens when the Lounge is finished (Lounge
   I built), plus its settle days — never on 《那面牆》, its settlement, the article or anything of 怡君's; each room opens
   when the one before it is done. Within a chain, one whose people cannot be here in this save does not hold the rest
   forever: once a later era of its own chain could start and it has waited 5 days (at once if the era before it is
   dormant too), it goes dormant — skipped, never shown as done — and it does not wake again after a later era of its
   chain has had its first beat. Two chains share only the day's story budget (the arbiter's caps). */
function xiuqin(){const m=crewByName('秀琴阿姨');return m&&m.role==='cleaner'?m:null}
const V24_ERAS=[
 {k:'yj',n:'怡君',can:()=>!!xqm()&&xqKnown(),begun:()=>fact('yj_meet'),done:()=>fact('yj_key')},
 {k:'wall',n:'那面牆',prev:'yj',settle:2,can:()=>!!xiuqin()&&xqKnown(),begun:()=>fact('wall_worry'),done:()=>fact('wall_settle')},
 {k:'up',n:'二樓',open:()=>loungeDoneDay(),settle:2,can:()=>upCan(),begun:()=>fact('up_hint'),done:()=>fact('up_lease')},   /* v2.4 P2: the stairs are in the side room; a restaurant with a crew. rc6 (10:25): after the Lounge, not after the wall */
];
/* the day the Lounge was finished (Lounge I built): its fact, else what the save kept of the project or the new room, else
   long enough ago (a save from before any of these were kept: the floor's era is simply open) */
function loungeDoneDay(){if(!(loungeLv()>=1))return null;const f=fact('lounge_built_1');if(f)return f.d;const p=S.loungeProj;if(p&&p.state==='built'&&p.at!=null)return p.at;const nr=S.newRooms&&S.newRooms.lounge;return nr?nr:0}
function eraOf(k){return V24_ERAS.find(e=>e.k===k)||null}
function eraLater(k){const out=[];let q=V24_ERAS.filter(e=>e.prev===k);while(q.length){const e=q.shift();out.push(e);q=q.concat(V24_ERAS.filter(x=>x.prev===e.k))}return out}   /* its own chain, after it */
function eraOpenDay(k){const v=v24();const E=eraOf(k);if(!E||v.dorm[k]!=null)return null;
 if(E.open){const d=E.open();return d==null?null:d+(E.settle||0)}if(!E.prev)return v.first;
 const P=eraOf(E.prev);const d=P&&P.done();if(d)return d.d+(E.settle||0);const pd=v.dorm[E.prev];return pd!=null?pd:null}
function eraOpen(k){const d=eraOpenDay(k);return d!=null&&S.day>=d}
function v24Dormancy(){const v=v24();
 for(const P of V24_ERAS){const later=eraLater(P.k);if(!later.length)continue;if(P.done()){v.wait[P.k]=0;continue}
  if(v.dorm[P.k]!=null){if(P.can()&&!later.some(N=>N.begun()))delete v.dorm[P.k];continue}
  const open=eraOpenDay(P.k);if(open==null||S.day<open){v.wait[P.k]=0;continue}
  if(!P.can()&&later.some(N=>N.can())){v.wait[P.k]=(v.wait[P.k]||0)+1;if((P.prev&&v.dorm[P.prev]!=null)||v.wait[P.k]>=5){v.dorm[P.k]=S.day;storyTrace({at:'v24',k:'dormant:'+P.k})}}else v.wait[P.k]=0}}
function v24Day(){v24Wx((S.today&&S.today.weather)||(R&&R.weather)||'sun');v24Dormancy()}
/* who the stories need today: each entry returns [{reg, p} | {name, p, type, o}] for the stages that are due; the
   schedule brings them with that chance (its own hash coins), so a due beat does not wait on a lucky visit */
const V24_WANTS=[];
/* rc8: the Madame Lin line's visits — she, the day her 「我做到月底」 is due; Ken, once he can have heard it */
V24_WANTS.push(()=>{const out=[];if(typeof linRetireReady!=='function')return out;if(linRetireReady()&&NAMED[LIN])out.push({name:LIN,p:.55,type:'vip',size:1,t:.35,k:'lin_retire'});
 if(fact('lin_retiring')&&!fact('ken_where')&&!fact('lounge_project')&&!loungeLv()&&NAMED[KEN])out.push({name:KEN,p:.5,type:'gourmet',size:1,t:.42,k:'ken_where'});return out});
/* §17: retired, not gone from the street: her first evening at The Lounge some days after it opens; after that, now and then */
V24_WANTS.push(()=>{const out=[];if(typeof loungeOpenTonight!=='function'||!loungeOpenTonight()||!NAMED[LIN]||!fact('lin_closed')||kenNightToday()||cnTonight())return out;const d0=loungeDoneDay();   /* not on a night the whole Lounge is booked (Ken's tasting, the chef's night): her evening is an ordinary one */if(d0==null)return out;
 if(!fact('lin_guest')){if(S.day>=d0+5&&evanOn())out.push({name:LIN,p:.6,type:'vip',size:1,t:.4,o:{lounge:1,lgRetry:1},k:'lin_guest'});return out}
 if(dayCoin('linlg|'+S.day)<8)out.push({name:LIN,p:1,type:'vip',size:1,t:.4+.3*dayCoin('linlgt|'+S.day)/100,o:{lounge:1,lgRetry:1}});return out});
function v24Visits(out,dur,roll){let want=[];for(const f of V24_WANTS){try{want=want.concat(f()||[])}catch(e){console.warn('[v24 want]',e)}}
 const grp={};const entry=w=>out.find(o=>w.reg?(o.reg===w.reg||(o.regs||[]).includes(w.reg)):(o.name===w.name||o.named===w.name));
 const resv=k=>{if(!k)return;const v=v24();if(!v.res||v.res.d!==S.day)v.res={d:S.day,k:[]};if(!v.res.k.includes(k))v.res.k.push(k)};
 for(const w of want){const key=w.reg||w.name;if(!key)continue;const tt=(w.t!=null?w.t:.22+.46*(hash('v24t|'+S.day+'|'+key)%100)/100)*dur;if(entry(w)){/* rc7.4 (found by the full run): already coming tonight anyway — they are still who the story is waiting for: a full room sends them back a little later, as it does anyone the story asked for (a regular's own visit used to be lost at the door, and the beat with it — Sophie, the day 怡君 was there for the article); and a beat that needs them at an hour has them then (the Wangs before 予安's trial piece) */const e=entry(w);e.story=1;if(w.t!=null&&w.o&&w.o.hold){e.t=tt;e.hold=1}if(w.o&&w.o.lounge){e.lounge=1;if(w.o.lgRetry)e.lgRetry=1}resv(w.k);continue}
  if(w.reg){const r=REG_BY[w.reg];if(!r||S.day<r.day)continue;if(!roll('v24|'+key,w.p))continue;const o=regPlanVisit({t:tt,type:r.type,reg:w.reg,size:r.size});o.story=1;out.push(o);resv(w.k)}
  else{if(!roll('v24|'+key,w.p))continue;out.push(Object.assign({t:tt,type:w.type||'regular',size:w.size||1,name:w.name,story:1},w.o||{}));resv(w.k)}}
 /* the people one beat needs together come around the same time (a nudge in the plan, like Sophie and Mia's) */
 for(const w of want){if(!w.grp)continue;const e=entry(w);if(e&&w.o&&w.o.lounge){e.lounge=1;if(w.o.lgRetry)e.lgRetry=1}/* v2.4 rc6: a pair that meets in the Lounge (Ken and 杜) */if(e&&!(grp[w.grp]=grp[w.grp]||[]).includes(e))grp[w.grp].push(e)}
 for(const k in grp){const es=grp[k];if(es.length<2)continue;const t0=Math.max(dur*.18,Math.min(...es.map(e=>e.t)));es.forEach((e,i)=>{e.v24grp=k;e.hold=1;/* the hour is the point: not pulled earlier on a quiet evening */e.t=Math.min(dur*.8,t0+i*(2+hash('v24g|'+S.day+'|'+k+'|'+i)%40/10))})}}
