const TIER_N={0:'陌生人',.5:'有點眼熟',1:'熟客',2:'Jill 的老客人'};
function jillSay(txt,o){if(shGrab({who:'jill',name:'Jill',text:txt,tone:o?jillTone(txt,o):undefined}))return;logLine('Jill',txt,'j');/* v2.2 Q: an authored moment (with someone who has a portrait) shows her face; an operational word stays a toast */if(o&&o.with&&portraitLine('jill',txt,{tone:jillTone(txt,o),with:o.with,withTone:o.withTone}))return;toast(`<b>Jill</b>：「${txt}」`,'q')}
function dishName(d){const D=DISH(d);return D?(d==='signature'&&S.signature?S.signature.name:d==='sigdessert'&&S.sigDessert?S.sigDessert.name:D.n):''}
