    if(st.lemon>0&&st.lemon<1){/* the slice on its way down from the fingers */c.save();c.translate(0,-9.5);c.scale(1,5.6/19.5);chLemonSlice(c,6,-3-(1-st.lemon)*130,7,0);c.restore()}
    if(stir){const a=now*7;c.strokeStyle='#C9D0D3';c.lineWidth=2.4;c.lineCap='round';c.beginPath();c.moveTo(Math.cos(a)*7,-10+Math.sin(a)*1.8);c.lineTo(Math.cos(a)*7+11,-38);c.stroke()}
