function srShadow(c,x,y,rx,ry,a){c.fillStyle=`rgba(100,76,48,${a||.16})`;el(c,x,y,rx,ry);c.fillStyle=`rgba(100,76,48,${(a||.16)*.6})`;el(c,x,y+ry*.2,rx*1.15,ry*1.5)}
