  if(reno){b.fillStyle='#C9B48E';b.fillRect(wx,wy,ww,wh);b.fillStyle='rgba(120,90,50,.25)';for(let k=0;k<5;k++)b.fillRect(wx,wy+6+k*12,ww,1);b.fillStyle='rgba(255,255,255,.5)';b.fillRect(wx+4,wy+2,10,3);b.fillRect(wx+ww-14,wy+wh-6,10,3)}
