 c.fillStyle='#4A4A50';c.fillRect(x-1.4,y-24,2.8,20);c.fillStyle='#2E2E33';rr(c,x-2.5,y-26,5,3,1);c.fill();c.fillStyle='#6E6E76';rr(c,x-4,y-10,8,2.2,1);c.fill();
