function scenePt(e){const r=sc.getBoundingClientRect();return{x:(e.clientX-r.left-SV.ox)/SV.s,y:(e.clientY-r.top-SV.oy)/SV.s}}
/* v2.2 X: with a mouse, the cursor says what can be tapped — the same targets as the tap below, nothing else */
function roomHot(p){if(room==='kitchen'){if(R&&!paused&&phase==='service'&&(hitStation(p)>=0||ddHit(p)))return true;const f=KR.fridge;if(p.x>=f.x-4&&p.x<=f.x+f.w+4&&p.y>=f.y-8&&p.y<=f.y+f.h+12)return true;if(S.rooms&&S.rooms.cooler){const k=KR.cooler;if(p.x>=k.x-4&&p.x<=k.x+k.w+4&&p.y>=k.y-8&&p.y<=k.y+k.h+12)return true}if(p.y>LH-70&&Math.abs(p.x-200)<60)return true;if(homeKDoorHit(p))return true;return false}
 if(room==='home'){if(!paused&&homeHitCat(p))return true;if(homeDoorHit(p))return true}
 if(room==='side'){const a=SIDE_L.arch;if(p.x>=a.x-8&&p.x<=a.x+a.w+8&&p.y>=a.y-6&&p.y<=a.y+112)return true}if(room==='front'&&R&&phase==='service'&&frontQueueAt(p))return true;if(room==='front'&&Math.abs(p.x-FR.door.x)<30&&p.y>176&&p.y<276)return true;if(room==='front'&&roomOpen('lounge')&&Math.abs(p.x-FR.ldoor.x)<22&&p.y>176&&p.y<276)return true;if(room==='lounge'&&loungeLv()&&Math.abs(p.x-LG.door.x)<20&&p.y>4&&p.y<112)return true;if(hitRegular(p)&&!paused)return true;if(!R||paused||phase!=='service')return false;
 for(const t of R.tables){if((t.room||'main')!==room)continue;if(t.pdr?pdHit(p):Math.hypot((p.x-t.x)*.85,p.y-(t.y-16))<(t.seats===4?46:40))return true}return false}
function sceneHot(p){if(room!=='main')return roomHot(p);if(S.rooms&&S.rooms.side&&p.x>=SIDE_ARCH.x-6&&p.x<=SIDE_ARCH.x+SIDE_ARCH.w+6&&p.y>=SIDE_ARCH.y-4&&p.y<=SIDE_ARCH.y+112)return true;if(paused)return false;if(hitCat(p)||hitRegular(p)||hitSpot(p))return true;if(p.y>FB-16&&hitKItem(p))return true;if(!R||phase!=='service')return false;
 for(const g of queued()){if((g.state!=='queue'&&g.state!=='arrive')||(g.room||'main')!=='main')continue;if(Math.hypot(p.x-g.x,p.y-(g.y-22))<26)return true}for(const t of R.tables){if((t.room||'main')!==room)continue;if(t.pdr?pdHit(p):Math.hypot((p.x-t.x)*.85,p.y-(t.y-16))<(t.seats===4?46:40))return true}return false}
sc.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;let hot=false;try{hot=sceneHot(scenePt(e))}catch(e2){hot=false}const want=hot?'pointer':'';if(sc.style.cursor!==want)sc.style.cursor=want});sc.addEventListener('pointerleave',()=>{sc.style.cursor=''});
sc.addEventListener('pointerdown',e=>{const p=scenePt(e);SW={x:e.clientX,y:e.clientY,t:performance.now(),hit:false};
 if(room!=='main'){if(roomTap(p,e))SW.hit=true;return}
 if(S.rooms&&S.rooms.side&&p.x>=SIDE_ARCH.x-6&&p.x<=SIDE_ARCH.x+SIDE_ARCH.w+6&&p.y>=SIDE_ARCH.y-4&&p.y<=SIDE_ARCH.y+112&&!hitCat(p)){e.preventDefault();SW.hit=true;setRoom('side');return}
 if(R&&!paused&&phase==='service'&&tapThief(p)){e.preventDefault();SW.hit=true;return}const ct=hitCat(p);if(ct&&!paused){e.preventDefault();tapCat(ct);return}const rg=hitRegular(p);if(rg&&!paused){e.preventDefault();const wt=regTableWork(rg);if(wt){SW.hit=true;tapTable(wt);idShowTable(wt);return}showRegCard(rg);idFocusGroup(rg,rg.hitWho||0,{soft:1});return}const hs=hitSpot(p);if(hs&&!paused){e.preventDefault();tapSpot(hs);return}if(!paused&&p.y>FB-16){const ki=hitKItem(p);if(ki){e.preventDefault();SW.hit=true;tapKItem(ki);return}}if(!R||paused||phase!=='service')return;e.preventDefault();audioInit();
 let best=null,bd=1e9;for(const g of queued()){if((g.state!=='queue'&&g.state!=='arrive')||(g.room||'main')!=='main')continue;const d=Math.hypot(p.x-g.x,p.y-(g.y-22));if(d<26&&d<bd){bd=d;best={g}}}
 for(const t of R.tables){if((t.room||'main')!==room)continue;const d=Math.hypot((p.x-t.x)*.85,p.y-(t.y-16));const lim=t.seats===4?46:40;if(d<lim&&d<bd){bd=d;best={t}}}
 if(!best){if(idHitWalker(p))SW.hit=true;return}SW.hit=true;if(best.g){const t=freeTableFor(best.g);if(t){seatGroup(best.g,t);idMark(idTableAt(t),idTableName(t),idPartyLine(best.g),{dur:1.9})}else{toast('目前沒有空桌，先收拾一下吧');idFocusGroup(best.g,0,{soft:1})}}else{tapTable(best.t);idShowTable(best.t)}});
function doCtrl(h){const s=h.s;switch(h.act){case'ing':actIng(s,h.arg);break;case'dose':actDose(s);break;case'doseDone':actDoseDone(s);break;case'tap':actTap(s);break;case'zone':actZone(s);break;case'hold':holdStart(s);break;case'close':R.panel=false;break;case'start':{const n=nextPendingFor(s.type);if(n)startCook(n.tk,n.it);break}}}
tc.addEventListener('pointerdown',e=>{if(!R||paused||phase!=='service')return;e.preventDefault();audioInit();const r=tc.getBoundingClientRect();const x=e.clientX-r.left,y=e.clientY-r.top;
 for(const h of TRAYHIT.chips){if(inR(h,x,y)){const s=R.slots[h.i];R.focus=h.i;R.focusLock=R.t+1.6;if(!s.job){const n=nextPendingFor(s.type);if(n)startCook(n.tk,n.it)}else sfx.tap();return}}
 for(const h of TRAYHIT.ctrls){if(inR(h,x,y)){if(h.act==='hold'){R.holdPtr=e.pointerId;try{tc.setPointerCapture(e.pointerId)}catch(e2){}}doCtrl(h);return}}
 if(TRAYHIT.stage&&inR(TRAYHIT.stage,x,y)){const s=R.slots[R.focus];if(s&&s.job&&s.job.step&&s.job.step.t==='tap')actTap(s)}});
